  $('refRoot').value=rr||0; $('song-root').value=sr||0; $('pr-key').value=pk||'all'; $('keyCtx').value=kc||'-1'; if(rn) $('refName').value=rn;
  const ssc=$('tr-sscale'); if(ssc&&ssc._filled){ const v=ssc.value; ssc.innerHTML=''; Object.keys(SCALES).forEach(nm=>{ const o=document.createElement('option'); o.value=nm; o.textContent=scaleDisp(nm); ssc.appendChild(o); }); ssc.value=v||'Major (Ionian)'; }
  const ap=$('ac-pat'); if(ap&&ap._filled){ const v=ap.value; ap.innerHTML=''; Object.keys(ACCOMP_PATTERNS).forEach(k=>{ const o=document.createElement('option'); o.value=k; o.textContent=ACCOMP_PATTERNS[k][lang]||ACCOMP_PATTERNS[k].en; ap.appendChild(o); }); ap.value=v||'block'; }
