    trx.ring.push(m); if(trx.ring.length>5) trx.ring.shift();
    const sm=trxMedian(), cents=Math.round(1200*Math.log2(f/midiToFreq(sm)));
    $('tr-live').innerHTML=noteName(sm,false)+'<small>'+(cents>=0?'+':'')+cents+'¢</small>';
