  const TPQN=480, bpm=trx.bpm||90, ev=[];
  trx.display.forEach(n=>{ const on=Math.round(n.sb*TPQN), off=on+Math.max(1,Math.round(n.db*TPQN)); ev.push({t:on,k:1,m:n.midi}); ev.push({t:off,k:0,m:n.midi}); });
