const CLEF_F='M252 262C78 262 0 135 0 39C0 -41 42 -110 123 -110C186 -110 229 -66 229 -4C229 60 182 100 133 100C106 100 96 93 83 93C70 93 67 101 67 111C67 151 127 224 229 224C335 224 381 120 381 -37C381 -140 359 -260 297 -356C237 -449 134 -534 10 -605C1 -610 -5 -615 -5 -623C-5 -629 -1 -635 8 -635C13 -635 19 -633 25 -630C158 -565 286 -489 392 -375C479 -281 531 -159 531 -28C531 146 425 262 252 262ZM629 180C598 180 574 156 574 125C574 94 598 70 629 70C660 70 684 94 684 125C684 156 660 180 629 180ZM630 -71C599 -71 576 -94 576 -125C576 -156 599 -179 630 -179C661 -179 684 -156 684 -125C684 -94 661 -71 630 -71Z';
const CLEF_SCALE=0.044;
function ssTrebleClef(x){ return srClef('treble',x,46); }
function ssBassClef(x){ return srClef('bass',x,46); }
function ssSharp(x,y){ return `<g class="ss-glyph"><line x1="${x}" y1="${y-6}" x2="${x}" y2="${y+6}" stroke="#1a1714" stroke-width="1"/><line x1="${x+3.4}" y1="${y-7}" x2="${x+3.4}" y2="${y+5}" stroke="#1a1714" stroke-width="1"/><line x1="${x-2}" y1="${y-2}" x2="${x+5.4}" y2="${y-3.2}" stroke="#1a1714" stroke-width="1.7"/><line x1="${x-2}" y1="${y+2.6}" x2="${x+5.4}" y2="${y+1.4}" stroke="#1a1714" stroke-width="1.7"/></g>`; }
function ssFlat(x,y){ return `<path class="ss-glyph" fill="none" stroke="#1a1714" stroke-width="1.4" stroke-linecap="round" d="M ${x-1},${y-9} L ${x-1},${y+4} C ${x+5},${y-1} ${x+4},${y-5} ${x-1},${y-1.5}"/>`; }
function ssNatural(x,y){ return `<g class="ss-glyph"><line x1="${x}" y1="${y-7}" x2="${x}" y2="${y+4}" stroke="#1a1714" stroke-width="1"/><line x1="${x+4}" y1="${y-4}" x2="${x+4}" y2="${y+7}" stroke="#1a1714" stroke-width="1"/><line x1="${x}" y1="${y-3.5}" x2="${x+4}" y2="${y-4.7}" stroke="#1a1714" stroke-width="1.5"/><line x1="${x}" y1="${y+2.2}" x2="${x+4}" y2="${y+1}" stroke="#1a1714" stroke-width="1.5"/></g>`; }
function ssAccGlyph(a,k,x,y){ return a>0?ssSharp(x,y):a<0?ssFlat(x,y):ssNatural(x,y); }
function ssNotehead(x,y,dur,onLine){ const filled=dur<2, rot=`rotate(-20 ${x} ${y})`;
  const e=`<ellipse class="ss-head${filled?'':' ss-hollow'}" cx="${x}" cy="${y}" rx="6" ry="4.4" transform="${rot}"/>`;
  const dot=[0.375,0.75,1.5,3].includes(dur)?`<circle class="ss-head" cx="${x+10}" cy="${onLine?y-6:y-1}" r="1.7"/>`:''; return e+dot; }
function ssStem(x,y,dur){ if(dur>=4) return ''; const up=y>70, sx=up?x+5.6:x-5.6, ey=up?y-32:y+32;
  let s=`<line class="ss-stem" x1="${sx}" y1="${y}" x2="${sx}" y2="${ey}" stroke="#1a1714" stroke-width="1.6"/>`;
  if(dur<=0.5) s+= up?`<path class="ss-flag" fill="none" stroke="#1a1714" stroke-width="1.8" d="M ${sx},${ey} C ${sx+9},${ey+5} ${sx+9},${ey+13} ${sx+3},${ey+17}"/>`:`<path class="ss-flag" fill="none" stroke="#1a1714" stroke-width="1.8" d="M ${sx},${ey} C ${sx+9},${ey-5} ${sx+9},${ey-13} ${sx+3},${ey-17}"/>`;
  return s; }
function ssLedger(x,y){ let s=''; if(y>94){ for(let ly=106;ly<=y+1;ly+=12) s+=`<line class="ss-ledger" x1="${x-9}" y1="${ly}" x2="${x+9}" y2="${ly}" stroke="#1a1714" stroke-width="1.2"/>`; } if(y<46){ for(let ly=34;ly>=y-1;ly-=12) s+=`<line class="ss-ledger" x1="${x-9}" y1="${ly}" x2="${x+9}" y2="${ly}" stroke="#1a1714" stroke-width="1.2"/>`; } return s; }
function ssKeySig(ex,x){ const refStep=ex.clef==='bass'?18:30, yOf=(li,oct)=>94+(refStep-ssStepOf(li,oct))*6;
  const sT=[[3,5],[0,5],[4,5],[1,5],[5,4],[2,5],[6,4]], fT=[[6,4],[2,5],[5,4],[1,5],[4,4],[0,5],[3,4]];
  const sB=[[3,3],[0,3],[4,3],[1,3],[5,2],[2,3],[6,2]], fB=[[6,2],[2,3],[5,2],[1,3],[4,2],[0,3],[3,2]];
  const n=ex.keyN, cnt=Math.abs(n), list=n>0?(ex.clef==='bass'?sB:sT):(ex.clef==='bass'?fB:fT); let svg='',xx=x;
  for(let i=0;i<cnt;i++){ const y=yOf(list[i][0],list[i][1]); svg+= n>0?ssSharp(xx+3,y):ssFlat(xx+3,y); xx+=9; }
  return {svg,w:cnt?cnt*9+6:6}; }
function ssTimeSig(ts,x){ return `<text class="ss-num" x="${x+9}" y="64">${ts[0]}</text><text class="ss-num" x="${x+9}" y="90">${ts[1]}</text>`; }
function ssRender(ex){
  const refStep=ex.clef==='bass'?18:30, yOf=(li,oct)=>94+(refStep-ssStepOf(li,oct))*6, keyAcc=ssKeyAcc(ex.keyN);
  let x=10, body='', noteX=[], idx=0;
  body+= ex.clef==='bass'?ssBassClef(x):ssTrebleClef(x); x+=30;
  const ks=ssKeySig(ex,x); body+=ks.svg; x+=ks.w;
  body+= ssTimeSig(ex.ts,x); x+=26;
  ex.measures.forEach((meas)=>{
    meas.forEach(note=>{
      const y=yOf(note.li,note.oct), nx=x+10; let g='';
      if(note.acc!==keyAcc[note.li]) g+=ssAccGlyph(note.acc,keyAcc[note.li],nx-13,y);
      g+= ssLedger(nx,y)+ssNotehead(nx,y,note.dur)+ssStem(nx,y,note.dur);
      const syl=ex.syl[((note.p%7)+7)%7];
      body+= `<g class="ss-n" data-i="${idx}"><rect class="ss-box" x="${nx-12}" y="40" width="24" height="58" rx="4"/>${g}<text class="ss-syl" x="${nx}" y="126">${syl}</text></g>`;
      noteX.push({x:nx,y,note,idx}); x+= 26+note.dur*15; idx++;
    });
    x+=6; body+= `<line class="ss-line" x1="${x}" y1="46" x2="${x}" y2="94" stroke="#1a1714" stroke-width="1.3"/>`; x+=12;
  });
  const W=Math.max(x+4,360); let staff='';
  [46,58,70,82,94].forEach(ly=> staff+=`<line class="ss-line" x1="8" y1="${ly}" x2="${W-6}" y2="${ly}" stroke="#1a1714" stroke-width="1.2"/>`);
  staff+= `<line class="ss-line" x1="8" y1="46" x2="8" y2="94" stroke="#1a1714" stroke-width="1.3"/>`;
  return {svg:`<svg class="ss-svg" viewBox="0 0 ${W} 150" width="${W}" height="150" xmlns="http://www.w3.org/2000/svg">${staff}${body}</svg>`, W, noteX};
}
/* ---- state + draw ---- */
const sing={ ex:null, render:null, level:0, clef:'treble', mode:'note', idx:0, active:false, results:[], bpm:80,
  runId:0, micRequest:0, analyser:null, stream:null, src:null, buf:null, raf:0, ring:[], stable:0, hint:0, samples:[], keyEvents:[],
  hlTimers:[], playRaf:0, playStart:0, loopA:null, loopB:null };
function ssFillLevels(){ const sel=$('si-level'); if(!sel||sel._filled) return; SS_LEVELS.forEach((L,i)=>{ const o=document.createElement('option'); o.value=i; o.textContent=(i+1)+' · '+L.name; sel.appendChild(o); }); sel._filled=true; }
function ssDraw(){ if(!sing.ex) return; const r=ssRender(sing.ex); sing.render=r; sing.flat=r.noteX.map(o=>o.note); const wrap=$('si-staff'); wrap.innerHTML=r.svg; wrap.classList.toggle('nosolf', !$('si-solf').checked); ssPaint(); }
function ssPaint(){ const svg=$('si-staff').querySelector('svg'); if(!svg) return; svg.querySelectorAll('.ss-n').forEach(g=>{ const i=+g.dataset.i, res=sing.results[i]; if((sing.mode==='note')&&sing.active&&i===sing.idx) g.dataset.s='now'; else if(res) g.dataset.s=res; else g.removeAttribute('data-s'); }); }
function ssNewExercise(){ sing.ex=ssGen(sing.level,sing.clef,0); sing.idx=0; sing.results=[]; sing.active=false; sing.bpm=sing.ex.bpm; const bp=$('si-bpm'); if(bp){ bp.value=sing.ex.bpm; $('si-bpmLbl').textContent=sing.ex.bpm; } ssDraw(); }
function renderSing(){ ssFillLevels(); if(!sing.ex||sing.ex.clef!==sing.clef||sing.ex.level!==sing.level) ssNewExercise(); else ssDraw(); ssModeUI(); }
function singStopAll(){
  sing.active=false; if(sing.raf) cancelAnimationFrame(sing.raf); sing.raf=0;
  ssMicStop(); ssRemoveCursor(); ssClearTrail();
  sing.hlTimers.forEach(clearTimeout); sing.hlTimers=[]; stopPreviews(); stopMetro(); stopDrone(); ssPaint();
  const g=$('si-go'); if(g) g.textContent=t(sing.mode==='free'?'si_play':'si_listen');
  const lv=$('si-live'); if(lv){ lv.textContent='—'; lv.classList.remove('rec'); }
}
function ssModeUI(){ const m=sing.mode; const tw=$('si-tempo-wrap'); if(tw) tw.style.display=(m==='note')?'none':'flex'; const go=$('si-go'); if(go) go.textContent=t(m==='free'?'si_play':'si_listen'); }

/* ---- pitch input (mic, shared with Transcribe's autocorrelation) ---- */
function ssMicStart(){ ensureAudio(); if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia) return Promise.resolve(false);
  const request=++sing.micRequest;
  return navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false}})
    .then(st=>{ if(request!==sing.micRequest||!sing.active||view0()!=='sing'){ st.getTracks().forEach(t=>t.stop()); return false; } sing.stream=st; sing.src=actx.createMediaStreamSource(st); sing.analyser=actx.createAnalyser(); sing.analyser.fftSize=2048; sing.buf=new Float32Array(sing.analyser.fftSize); sing.src.connect(sing.analyser); return true; }).catch(()=>false); }
function ssMicMaybe(){ return sing.analyser?Promise.resolve(true):ssMicStart(); }
function ssMicStop(){ sing.runId++; sing.micRequest++; if(sing.src){ try{sing.src.disconnect()}catch(_){} sing.src=null; } if(sing.stream){ sing.stream.getTracks().forEach(t=>t.stop()); sing.stream=null; } sing.analyser=null; }
function ssReadPitch(){ if(!sing.analyser) return null; sing.analyser.getFloatTimeDomainData(sing.buf); const f=trxAutoCorrelate(sing.buf,actx.sampleRate); if(f<0) return null; const midi=Math.round(69+12*Math.log2(f/440)), cents=Math.round(1200*Math.log2(f/(440*Math.pow(2,(midi-69)/12)))); return {f,midi,cents}; }
function ssNeed(targetPc,sungPc){ let d=((targetPc-sungPc)%12+12)%12; if(d>6) d-=12; return d; }   // + → sing higher
function ssCurNote(){ return sing.flat?sing.flat[sing.idx]:null; }

/* ---- cursor + trail + scroll ---- */
function ssSvg(){ return $('si-staff').querySelector('svg'); }
function ssCursorEl(){ const svg=ssSvg(); if(!svg) return null; let c=svg.querySelector('.ss-playhead'); if(!c){ c=document.createElementNS('http://www.w3.org/2000/svg','line'); c.setAttribute('class','ss-playhead'); c.setAttribute('y1','38'); c.setAttribute('y2','102'); svg.appendChild(c); } return c; }
function ssMoveCursor(x){ const c=ssCursorEl(); if(c){ c.setAttribute('x1',x); c.setAttribute('x2',x); } ssScrollToX(x); }
function ssRemoveCursor(){ const svg=ssSvg(), c=svg&&svg.querySelector('.ss-playhead'); if(c) c.remove(); }
function ssScrollToX(x){ const w=$('si-staff'); if(w.scrollWidth>w.clientWidth+4) w.scrollLeft=Math.max(0,x-w.clientWidth*0.4); }
function ssScrollToCur(){ const o=sing.render&&sing.render.noteX[sing.idx]; if(o) ssScrollToX(o.x); }
function ssPitchY(f){ const bottomMidi=sing.ex.clef==='bass'?43:64, midi=69+12*Math.log2(f/440); let y=94-(midi-bottomMidi)*3.5; while(y>142) y-=42; while(y<4) y+=42; return y; }
function ssDrawTrail(){ const svg=ssSvg(); if(!svg) return; let pl=svg.querySelector('.ss-trail'); if(!pl){ pl=document.createElementNS('http://www.w3.org/2000/svg','polyline'); pl.setAttribute('class','ss-trail'); svg.appendChild(pl); } pl.setAttribute('points', sing.trail.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' ')); }
function ssClearTrail(){ const svg=ssSvg(), pl=svg&&svg.querySelector('.ss-trail'); if(pl) pl.remove(); }
function ssBeatToX(beat){ const ns=sing.render&&sing.render.noteX; if(!ns||!ns.length) return 10; const pts=ns.map(o=>({b:o.note.tBeat,x:o.x})); pts.push({b:sing.ex.totalBeats,x:sing.render.W-12});
  for(let i=0;i<pts.length-1;i++){ if(beat>=pts[i].b&&beat<=pts[i+1].b){ const f=(beat-pts[i].b)/Math.max(1e-3,pts[i+1].b-pts[i].b); return pts[i].x+f*(pts[i+1].x-pts[i].x); } }
  return beat<=pts[0].b?pts[0].x:pts[pts.length-1].x; }

/* ---- reference cues ---- */
function ssTonic(){ if(!sing.ex) return; ensureAudio(); previewNote(sing.ex.tonicMidi, actx.currentTime+0.02, 0.85, 92); }
// A pulse running along the staff while the melody plays; with reduced motion the notes simply stay as they are.
function ssFlash(i){ if(reduceMotion()) return; const svg=ssSvg(); if(!svg) return; const g=svg.querySelector('.ss-n[data-i="'+i+'"]'); if(!g) return; const prev=g.getAttribute('data-s'); g.dataset.s='now'; sing.hlTimers.push(setTimeout(()=>{ if(g.dataset.s==='now'){ if(prev&&prev!=='now') g.dataset.s=prev; else g.removeAttribute('data-s'); } },240)); }
function ssPlayIt(){ if(!sing.ex||!sing.flat) return; ensureAudio(); stopPreviews(); sing.hlTimers.forEach(clearTimeout); sing.hlTimers=[]; const beatSec=60/(sing.bpm||sing.ex.bpm), t0=actx.currentTime+0.12;
  sing.flat.forEach((n,i)=>{ const when=t0+n.tBeat*beatSec, dur=Math.max(0.18,n.dur*beatSec*0.92); previewNote(n.midi,when,dur,92); sing.hlTimers.push(setTimeout(()=>ssFlash(i),Math.max(0,(when-actx.currentTime)*1000))); }); }
function ssDrone(){ if($('si-drone').checked){ if(sing.ex){ ensureAudio(); startDrone(pc(sing.ex.tonicMidi)); } } else stopDrone(); }

/* ---- mode: note-by-note ---- */
function ssNoteStart(){ sing.active=true; sing.idx=0; sing.results=[]; sing.hint=0; sing.holdT=0; sing.wrongT=0; ssPaint(); ssScrollToCur();
  $('si-verdict').className='verdict neutral'; $('si-verdict').textContent=t('si_singit'); ensureAudio(); previewNote(sing.ex.tonicMidi,actx.currentTime+0.02,0.6,85);
  const run=sing.runId; ssMicMaybe().then(ok=>{ if(run===sing.runId&&sing.active&&sing.mode==='note'){ if(!ok) $('si-hint').textContent=t('si_nomic'); sing.raf=requestAnimationFrame(ssNoteLoop); } }); }
function ssNoteLoop(ts){ if(!sing.active||sing.mode!=='note') return; const cur=ssCurNote(), tgt=cur?pc(cur.midi):-1, p=ssReadPitch(), lv=$('si-live');
  if(p){ lv.classList.add('rec'); lv.innerHTML=noteName(p.midi,false)+'<small>'+(p.cents>=0?'+':'')+p.cents+'¢</small>';
    if(pc(p.midi)===tgt && Math.abs(p.cents)<42){ if(!sing.holdT) sing.holdT=ts; else if(ts-sing.holdT>=320){ ssNoteCorrect(); } sing.wrongT=0; }
    else { sing.holdT=0; if(!sing.wrongT) sing.wrongT=ts; else if(ts-sing.wrongT>700){ sing.wrongT=0; ssHintBump(p.midi); } } }
  else { lv.classList.remove('rec'); sing.holdT=0; }
  sing.raf=requestAnimationFrame(ssNoteLoop); }
function ssNoteCorrect(){ if(!sing.active) return; sing.results[sing.idx]='good'; sing.holdT=0; sing.wrongT=0; sing.hint=0; $('si-hint').textContent=''; sing.idx++; ssPaint(); ssScrollToCur();
  if(sing.idx>=sing.flat.length) ssNoteFinish(); }
function ssHintBump(am){ const cur=ssCurNote(); if(!cur) return; sing.hint++; const need=ssNeed(pc(cur.midi),pc(am)), syl=sing.ex.syl[((cur.p%7)+7)%7];
  if(sing.hint===1) $('si-hint').textContent= need>0?t('si_hi_up'):t('si_hi_down');
  else { $('si-hint').textContent=t('si_hi_syl',syl); ensureAudio(); previewNote(cur.midi,actx.currentTime+0.02,0.6,80); } }
function ssNoteFinish(){ sing.active=false; if(sing.raf) cancelAnimationFrame(sing.raf); sing.raf=0; ssMicStop(); ssPaint();
  const tot=sing.flat.length; const v=$('si-verdict'); v.className='verdict good'; v.textContent=t('si_perfect'); $('si-go').textContent=t('si_listen'); $('si-live').textContent='—'; $('si-hint').textContent=''; ssBumpProgress(tot,tot); }

/* ---- mode: phrase ---- */
function ssPhraseStart(){ sing.active=true; sing.results=[]; sing.samples=[]; sing.keyEvents=[]; ssPaint(); $('si-hint').textContent='';
  ensureAudio(); const run=sing.runId; ssMicMaybe().then(ok=>{ if(run!==sing.runId||!sing.active||sing.mode!=='phrase') return; if(!ok) $('si-hint').textContent=t('si_nomic'); const beatSec=60/sing.bpm, ci=sing.ex.ts[0];
    sing.countInMs=ci*beatSec*1000; sing.phraseStartPN=performance.now()+150; sing.phraseSingPN=sing.phraseStartPN+sing.countInMs;
    const t0=actx.currentTime+0.15+ (sing.phraseStartPN-performance.now())/1000; for(let b=0;b<ci;b++) metroClick(t0+b*beatSec, b===0);   // audible count-in (best-effort)
    $('si-verdict').className='verdict neutral'; $('si-verdict').textContent=t('si_count'); sing.raf=requestAnimationFrame(ssPhraseLoop); }); }
function ssPhraseLoop(ts){ if(!sing.active||sing.mode!=='phrase') return; const beatSec=60/sing.bpm, dur=sing.ex.totalBeats*beatSec;
  if(ts<sing.phraseSingPN){ $('si-verdict').textContent=t('si_count'); ssMoveCursor(ssBeatToX(0)); sing.raf=requestAnimationFrame(ssPhraseLoop); return; }
  const tt=(ts-sing.phraseSingPN)/1000;
  if(tt<=dur){ $('si-verdict').textContent=t('si_sing_now'); const p=ssReadPitch(); if(p) sing.samples.push({t:tt,pc:pc(p.midi),cents:p.cents}); const lv=$('si-live'); if(p){ lv.classList.add('rec'); lv.innerHTML=noteName(p.midi,false); } else lv.classList.remove('rec'); ssMoveCursor(ssBeatToX(tt/beatSec)); sing.raf=requestAnimationFrame(ssPhraseLoop); }
  else ssPhraseGrade(); }
function ssPhraseGrade(){ sing.active=false; if(sing.raf) cancelAnimationFrame(sing.raf); sing.raf=0; ssMicStop(); ssRemoveCursor(); const beatSec=60/sing.bpm;
  sing.flat.forEach((n,i)=>{ const s=n.tBeat*beatSec, e=(n.tBeat+n.dur)*beatSec, tpc=pc(n.midi);
    const win=sing.samples.filter(x=>x.t>=s-0.05&&x.t<=e), onp=win.filter(x=>x.pc===tpc), frac=win.length?onp.length/win.length:0;
    let verdict= frac>0.55?'good':frac>0.18?'near':'bad';
    if(sing.keyEvents.some(k=>pc(k.midi)===tpc&&k.t>=s-0.18&&k.t<=e+0.05) && verdict!=='good') verdict='good';
    sing.results[i]=verdict; });
  ssPaint(); const good=sing.results.filter(r=>r==='good').length, tot=sing.flat.length; const v=$('si-verdict'); v.className='verdict '+(good===tot?'good':'neutral'); v.textContent= good===tot?t('si_perfect'):t('si_nicetry',good,tot);
  $('si-live').textContent='—'; $('si-go').textContent=t('si_listen'); ssBumpProgress(good,tot); }

/* ---- mode: free (follow-along scroll + pitch trail) ---- */
function ssFreeStart(){ sing.active=true; sing.trail=[]; ssClearTrail(); ssPaint();
  ensureAudio(); const run=sing.runId; ssMicMaybe().then(ok=>{ if(run!==sing.runId||!sing.active||sing.mode!=='free') return; if(!ok){ singStopAll(); const v=$('si-verdict'); v.className='verdict bad'; v.textContent=t('tr_micfail'); return; } if($('si-drone').checked) startDrone(pc(sing.ex.tonicMidi)); sing.freePN=performance.now()+100; $('si-verdict').className='verdict neutral'; $('si-verdict').textContent=t('si_freehint'); sing.raf=requestAnimationFrame(ssFreeLoop); }); }
function ssFreeLoop(ts){ if(!sing.active||sing.mode!=='free') return; const beatSec=60/sing.bpm, dur=sing.ex.totalBeats*beatSec; let tt=(ts-sing.freePN)/1000;
  if(tt>dur+0.4){ sing.freePN=ts; sing.trail=[]; ssClearTrail(); tt=0; }
  const x=ssBeatToX(Math.min(Math.max(tt,0),dur)/beatSec); ssMoveCursor(x); const p=ssReadPitch(), lv=$('si-live');
  if(p){ lv.classList.add('rec'); lv.innerHTML=noteName(p.midi,false)+'<small>'+(p.cents>=0?'+':'')+p.cents+'¢</small>'; sing.trail.push([x,ssPitchY(p.f)]); if(sing.trail.length>400) sing.trail.shift(); ssDrawTrail(); }
  else lv.classList.remove('rec');
  sing.raf=requestAnimationFrame(ssFreeLoop); }

/* ---- input from keyboard / MIDI (alternative to singing) ---- */
function singKeyInput(m){ if(!sing.active) return; if(sing.mode==='note'){ const cur=ssCurNote(); if(!cur) return; if(pc(m)===pc(cur.midi)) ssNoteCorrect(); else ssHintBump(m); } else if(sing.mode==='phrase'){ sing.keyEvents.push({t:(performance.now()-sing.phraseSingPN)/1000,midi:m}); } }

/* ---- dispatcher + light progress ---- */
function singGo(){ if(!sing.ex) return; if(sing.active){ singStopAll(); $('si-verdict').textContent=''; return; }
  $('si-hint').textContent=''; sing.bpm=+($('si-bpm').value||sing.ex.bpm);
  if(sing.mode==='note') ssNoteStart(); else if(sing.mode==='phrase') ssPhraseStart(); else ssFreeStart();
  $('si-go').textContent=t('si_stop'); }
function ssBumpProgress(good,tot){ if(sing.mode!=='free' && good===tot && tot>0){ data.singCleared=data.singCleared||{}; data.singCleared[sing.level]=true; saveAll(); } }

/* ---------- KEYBOARD ---------- */
const BASE_LOW=24, BASE_HIGH=96; const view={low:48,oct:4}; let labelMode='c';
let typeOctave=60;
function clampTypeOctave(){ const lo=view.low, maxLo=Math.max(lo,viewHigh()-12); typeOctave=Math.max(lo,Math.min(maxLo,Math.round(typeOctave/12)*12)); }
const whiteEl=new Map(), blackEl=new Map(), keyEl=new Map();
const BLACK_NUDGE={1:-.28,3:.28,6:-.30,8:0,10:.30};
function viewHigh(){ return view.low+view.oct*12; }
function chooseView(){ const w=window.innerWidth; view.oct=w<560?2:w<900?3:4; view.low=Math.max(BASE_LOW,Math.min(view.low,BASE_HIGH-view.oct*12)); clampTypeOctave(); }
function buildKeyboard(){ clampTypeOctave();
  const keys=$('keys'); if(!keys) return; const active=document.activeElement, focused=keys.contains(active)?Number(active.dataset.midi):null;
  keys.innerHTML=''; whiteEl.clear(); blackEl.clear(); keyEl.clear();
  const lo=view.low, hi=viewHigh(), WHITE=new Set([0,2,4,5,7,9,11]);
  for(let m=lo;m<=hi;m++){ if(!WHITE.has(pc(m))) continue;
    const b=document.createElement('button'); b.className='key white'; b.dataset.midi=m; b.type='button'; b.tabIndex=0; b.setAttribute('aria-label',noteName(m,false));
    if(m===60) b.classList.add('midc');
    if(labelMode!=='none' && (labelMode==='all' || pc(m)===0)){ const l=document.createElement('span'); l.className='lbl'; l.textContent= pc(m)===0 ? rootName(0)+(Math.floor(m/12)-1) : pcName(pc(m),false); b.appendChild(l); }
    const mk=document.createElement('span'); mk.className='mk'; b.appendChild(mk); const dg=document.createElement('span'); dg.className='dg'; dg.setAttribute('aria-hidden','true'); b.appendChild(dg); keys.appendChild(b); whiteEl.set(m,b); keyEl.set(m,b); bindKeyA11y(b,m);
  }
  for(let m=lo;m<=hi;m++){ if(WHITE.has(pc(m))) continue;
    const b=document.createElement('button'); b.className='key black'; b.dataset.midi=m; b.type='button'; b.tabIndex=0; b.setAttribute('aria-label',noteName(m,false));
    const mk=document.createElement('span'); mk.className='mk'; b.appendChild(mk); const dg=document.createElement('span'); dg.className='dg'; dg.setAttribute('aria-hidden','true'); b.appendChild(dg); keys.appendChild(b); blackEl.set(m,b); keyEl.set(m,b); bindKeyA11y(b,m);
  }
  positionBlacks();
  if(focused!=null){ const key=keyEl.get(Math.max(lo,Math.min(hi,focused))); if(key){
    key.focus({preventScroll:true});
    const scroll=$('dock-keys'), r=key.getBoundingClientRect(), s=scroll.getBoundingClientRect();
    if(r.left<s.left) scroll.scrollLeft+=r.left-s.left;
    else if(r.right>s.right) scroll.scrollLeft+=r.right-s.right;
  } }
  const oi=$('octInd'); if(oi) oi.textContent=noteName(view.low,false)+'–'+noteName(viewHigh(),false);
  kbDegrees(kbDegSrc);
  if(view0()==='analysis') anKeysPaint(true);
  cofPaintDock();
}
// Chord-member numbers (1 3 5 7 …) shown on keys; `src` maps sounding MIDI notes to labels and is folded into view.
let kbDegSrc=null;
function kbDegrees(src){
  kbDegSrc=src&&src.size?src:null; const folded=new Map();
  if(kbDegSrc) kbDegSrc.forEach((label,m)=>folded.set(foldToView(m),label));
  keyEl.forEach((el,m)=>{ const label=folded.get(m)||'', d=el.querySelector('.dg');
    const degDesc=label?(label==='R'?t('kb_deg_r'):t('kb_deg',label)):'';
    if(d){ d.textContent=label; if(degDesc) d.title=degDesc; else d.removeAttribute('title'); }
    if(degDesc) el.title=noteName(m,false)+' — '+degDesc; else el.removeAttribute('title');
    el.setAttribute('aria-label',noteName(m,false)+(degDesc?', '+degDesc:'')); });
}
// Generic chord-member label for a pitch class `rel` semitones above the root of a chord with relative pitch classes `pcs`.
function chordToneLabel(rel,pcs){ const has=x=>pcs.includes(x), third=has(3)||has(4);
  switch(rel){ case 0: return 'R'; case 3: case 4: return third&&has(3)&&has(4)&&rel===3?'♯9':'3'; case 7: return '5';
    case 6: return has(7)?'♯11':'5'; case 8: return has(7)?'♭13':'5'; case 10: case 11: return '7';
    case 9: return has(3)&&has(6)&&!has(10)&&!has(11)?'7':(has(10)||has(11))?'13':'6';
    case 1: return '♭9'; case 2: return third?'9':'2'; case 5: return third?'11':'4'; }
  return ''; }
function chordDegreeMap(midis,rootPc,pcs){ const map=new Map(); midis.forEach(m=>{ const rel=((pc(m)-rootPc)%12+12)%12; if(pcs.includes(rel)){ const l=chordToneLabel(rel,pcs); if(l) map.set(m,l); } }); return map; }
function positionBlacks(){ blackEl.forEach((el,bm)=>{ const w=whiteEl.get(bm-1); if(!w||!w.offsetWidth) return; const bw=w.offsetWidth*.62, seam=w.offsetLeft+w.offsetWidth, n=(BLACK_NUDGE[pc(bm)]||0)*bw; el.style.width=bw+'px'; el.style.left=(seam-bw/2+n)+'px'; }); syncKeyboardPan(); }
function syncKeyboardPan(){ const scroll=$('dock-keys'), pan=$('kb-pan'), max=Math.max(0,scroll.scrollWidth-scroll.clientWidth); pan.max=String(max); pan.value=String(scroll.scrollLeft); pan.hidden=!dockShown()||max<1; }
function reflowKeys(){ requestAnimationFrame(()=>requestAnimationFrame(positionBlacks)); setTimeout(positionBlacks,90); }   // wait for the dock to lay out before measuring
function foldToView(m){ const lo=view.low,hi=viewHigh(); let x=m; while(x<lo)x+=12; while(x>hi)x-=12; return x; }
function kbState(midi,s,fold){ const m=fold?foldToView(midi):midi, el=keyEl.get(m); if(!el) return; if(s) el.dataset.s=s; else delete el.dataset.s; const mk=el.querySelector('.mk'); if(mk) mk.textContent=s==='good'?'✓':s==='bad'?'✗':''; }
function kbClear(s){ keyEl.forEach(el=>{ if(el.dataset.s===s) delete el.dataset.s; const mk=el.querySelector('.mk'); if(mk&&!el.dataset.s) mk.textContent=''; }); }
function kbClearAll(){ keyEl.forEach(el=>{ delete el.dataset.s; const mk=el.querySelector('.mk'); if(mk) mk.textContent=''; }); }
function kbPress(midi,on){ const m=foldToView(midi), el=keyEl.get(m); if(!el) return; if(!on&&[...held].some(n=>foldToView(n)===m)) return; el.classList.toggle('pressed',on); if(on){ if(!el.dataset.s) el.dataset.s='active'; } else if(el.dataset.s==='active') delete el.dataset.s; }
function repaintHeld(){ held.forEach(m=>kbPress(m,true)); }
const pointerKey=new Map();
function keyAt(x,y){ const el=document.elementFromPoint(x,y); if(el){ const k=el.closest('.key'); if(k) return +k.dataset.midi; } return null; }
function initPointer(){ const kb=$('keys');
  kb.addEventListener('pointerdown',e=>{ const m=keyAt(e.clientX,e.clientY); if(m==null) return; e.preventDefault(); try{kb.setPointerCapture(e.pointerId)}catch(_){}; pointerKey.set(e.pointerId,m); handleNoteOn(m,100,'pointer:'+e.pointerId); });
  kb.addEventListener('pointermove',e=>{ if(!pointerKey.has(e.pointerId)) return; const cur=pointerKey.get(e.pointerId), m=keyAt(e.clientX,e.clientY); if(m!==cur){ if(cur!=null) handleNoteOff(cur,'pointer:'+e.pointerId); pointerKey.set(e.pointerId,m); if(m!=null) handleNoteOn(m,100,'pointer:'+e.pointerId); } });
  const end=e=>{ if(pointerKey.has(e.pointerId)){ const m=pointerKey.get(e.pointerId); if(m!=null) handleNoteOff(m,'pointer:'+e.pointerId); pointerKey.delete(e.pointerId); } };
  kb.addEventListener('pointerup',end); kb.addEventListener('pointercancel',end); kb.addEventListener('lostpointercapture',end);
}
function bindKeyA11y(b,m){ b.addEventListener('keydown',e=>{ if(e.key===' '||e.key==='Enter'){ e.preventDefault(); if(!b._kd){ b._kd=true; handleNoteOn(m,100,'button:'+m); } } }); b.addEventListener('keyup',e=>{ if(e.key===' '||e.key==='Enter'){ e.preventDefault(); b._kd=false; handleNoteOff(m,'button:'+m); } }); b.addEventListener('blur',()=>{ if(b._kd){ b._kd=false; handleNoteOff(m,'button:'+m); } }); }

/* ---------- KEYBOARD DOCK: the keys, or folded into a slim rail; one choice for every view ----------
   Hiding only hides the on-screen keys: MIDI and the computer keys keep playing, and the rail keeps one Show keyboard button.
   Without a choice the keys are open, except in Score & analysis on small screens, where the score needs the room; that default
   is settled once per visit, so resizing the window never flips the keyboard (or what its buttons do) behind the user's back.
   Falling notes draw their own keyboard, so that view shows neither the dock nor the rail and leaves the choice untouched. */
const DOCK={pref:null,auto:null,animT:0};
function dockWanted(v=view0()){ return v==='today'||v==='explore'||v==='accompany'||v==='transcribe'||v==='learn'||v==='read'||v==='sing'||(v===sesHome()&&SES.active)||(v==='analysis'&&anDockWanted()); }
function dockOpen(v=view0()){ if(DOCK.pref!=null) return DOCK.pref; return false; }
function dockShown(){ return document.body.classList.contains('kb')&&!$('dock').classList.contains('is-rail'); }
// The dock's own button names the action it takes (Hide / Show keyboard).
function dockLabels(){ const open=dockOpen(), act=t(open?'kb_hide':'kb_show'), dk=$('dock-kb-toggle');
 dk.setAttribute('aria-expanded',open?'true':'false'); dk.title=act; dk.querySelector('.dock-kb-label').textContent=act; }
function dockSync(){
 const dock=$('dock'), v=view0(), on=dockWanted(v), open=on&&dockOpen(v), was=document.body.classList.contains('kb'), wasOpen=dockShown();
 dock.classList.toggle('compact',v==='analysis'); $('dock-kb-toggle').hidden=!on; dockLabels();
 if(on===was&&open===wasOpen) return;
 document.body.classList.toggle('kb',on); dock.classList.toggle('is-rail',on&&!open);
 if(open){ if(was&&!wasOpen) dockReveal(); if(v==='analysis'&&AN.kbCenter) anKeysCenter(); positionBlacks(); reflowKeys(); if(v==='analysis') anKeysPaint(true); }
 else { dock.classList.remove('is-opening'); if(v==='analysis') anKeysClear(); }
 anLayoutVars();   // size the page and the score from the dock's new height in this same frame: no stale gap, no overlap
}
// Expanding from the rail, the keys rise out of it (not with reduced motion); transform and opacity only, so the layout is settled from the first frame.
function dockReveal(){ if(reduceMotion()) return; const dock=$('dock'); dock.classList.add('is-opening'); clearTimeout(DOCK.animT); DOCK.animT=setTimeout(()=>dock.classList.remove('is-opening'),300); }
function dockSet(open){ const keep=view0()==='analysis'?anKeepPlace():dockKeepEnd(open);
 DOCK.pref=!!open; saveAll(); if(view0()==='analysis') anUpdateControls(); else dockSync(); keep(); }
// Other pages scroll under the dock: whoever is reading the end of a long page still sees it when the keys come back.
function dockKeepEnd(open){ const root=document.scrollingElement||document.documentElement, end=open&&root.scrollHeight>innerHeight+2&&root.scrollTop>0&&root.scrollTop+innerHeight>=root.scrollHeight-2;
 return ()=>{ if(end) window.scrollTo(0,root.scrollHeight); }; }

/* ---------- INPUT ROUTING ---------- */
const held=new Set(), heldOrder=[], sustained=new Set(), inputOwners=new Map(); let pedalDown=false, evalTimer=null;
function handleNoteOn(midi,vel,source='midi'){
  if(!Number.isInteger(midi)||midi<0||midi>127) return;
  ensureAudio();
  const owners=inputOwners.get(midi)||new Set(); owners.add(source); inputOwners.set(midi,owners);
  if(held.has(midi)) return; sustained.delete(midi); held.add(midi); heldOrder.push(midi); audioNoteOn(midi,vel); kbPress(midi,true); wakePing(); onInputChange('on',midi); }
function handleNoteOff(midi,source='midi'){
  const owners=inputOwners.get(midi); if(!owners||!owners.delete(source)) return;
  if(owners.size) return; inputOwners.delete(midi);
  if(!held.has(midi)) return; held.delete(midi); const i=heldOrder.indexOf(midi); if(i>=0) heldOrder.splice(i,1); kbPress(midi,false); if(pedalDown) sustained.add(midi); else audioNoteOff(midi); onInputChange('off',midi); }
function pedalUp(){ sustained.forEach(m=>{ if(!held.has(m)) audioNoteOff(m); }); sustained.clear(); }
function heldMidis(){ return [...held]; }
function heldPcs(){ return [...new Set(heldMidis().map(pc))].sort((a,b)=>a-b); }
function releaseLiveInput(){
  held.forEach(m=>audioNoteOff(m)); sustained.forEach(m=>audioNoteOff(m));
  held.clear(); heldOrder.length=0; sustained.clear(); inputOwners.clear();
  pointerKey.clear(); typingDown.clear(); pedalDown=false;
  keyEl.forEach(el=>{ el._kd=false; el.classList.remove('pressed'); if(el.dataset.s==='active') delete el.dataset.s; });
}
// Without focus no key-up or pointer-up arrives, so keys held from the computer keyboard, the screen or a rhythm pad are let go as if
// lifted (drills see an ordinary release). MIDI and Bluetooth go on reporting, so keys and pedal held on the instrument stay as they are.
function releaseFocusInput(){ let fell=false;
  [...inputOwners.entries()].forEach(([m,o])=>[...o].forEach(s=>{ if(s==='midi'||s==='ble') return; if(s.startsWith('fall:')) fell=true; handleNoteOff(m,s); }));
  pointerKey.clear(); typingDown.clear(); if(FALL.press) FALL.press.clear(); RD.kbDown=null; keyEl.forEach(el=>{ el._kd=false; });
  if(RD.rh) [...RD.rh.open.keys()].forEach(s=>{ if(/^(k:|p\d)/.test(s)) rdRhRelease(s); });
  if(fell&&!FALL.raf) fallDraw(); }
function panic(){ scorePause(); releaseLiveInput(); trxStop(); accompStop(); trx.hlTimers.forEach(clearTimeout); trx.hlTimers=[]; singStopAll(); srStopAll(true); held.forEach(m=>audioNoteOff(m)); held.clear(); heldOrder.length=0; sustained.forEach(m=>audioNoteOff(m)); sustained.clear(); liveVoices.forEach(v=>v.stop()); liveVoices.clear(); stopPreviews(); stopDrone(); pointerKey.clear(); typingDown.clear(); pedalDown=false; bendSemitones=0; if(lfoGain&&actx) lfoGain.gain.setTargetAtTime(0,actx.currentTime,.02); keyEl.forEach(el=>{ el.classList.remove('pressed'); if(el.dataset.s==='active') delete el.dataset.s; }); if(view0()==='explore') updateExplore(); }
// midi is the key that just went down or (physically) came up; the sustain pedal never delays an 'off'.
function onInputChange(kind,midi){
  if(view0()==='analysis'){ pracInput(kind); return; }
  if(view0()==='explore'){ updateExplore(); return; }
  if(view0()==='learn' && kind==='on'){ learnInput(); return; }
  if(view0()==='sing' && sing.active && kind==='on'){ const m=heldOrder[heldOrder.length-1]; if(m!=null) singKeyInput(m); return; }
  if(view0()==='read' && RD.on && RD.L && RD.L.ty==='rh'){ if(midi!=null) rdRhKey(kind,midi); return; }
  if(view0()==='read' && RD.on && kind==='on'){ const m=heldOrder[heldOrder.length-1]; if(m!=null) rdInput(m); return; }
  if(view0()==='read' && SR.active && kind==='on'){ const m=heldOrder[heldOrder.length-1]; if(m!=null) srKeyInput(m); return; }
  if(SES.active){ if(kind==='on') sesInput(midi); else if(SES.q&&SES.q.ek) ekOff(SES.q,midi); }
}
function scheduleEval(fn,ms){ clearTimeout(evalTimer); evalTimer=setTimeout(fn,ms); }

/* ---------- WEB MIDI ---------- */
let midiAccess=null, activeInputId=null, savedDevice=null, midiMsg=null;
function setMidi(text,cls){ midiMsg={text,cls}; const s=$('set-midi-status'); if(s) s.textContent=text; midiChipSync(); }
// The header chip names the Web MIDI input when one is live, else a live Bluetooth MIDI piano, else the Web MIDI status.
function midiChipSync(){ const mt=$('midiText'), md=$('midiDot'); if(!mt||!md) return;
  if(!(midiMsg&&midiMsg.cls==='on')&&bleLive()){ mt.textContent=t('ble_on',bleName()); md.className='dot on'; return; }
  mt.textContent=midiMsg?midiMsg.text:t('midi_connect'); md.className='dot'+(midiMsg&&midiMsg.cls?' '+midiMsg.cls:''); }
async function connectMidi(){ ensureAudio();
  if(!navigator.requestMIDIAccess){ setMidi(t('midi_unsupported'),'err'); return; }
  if(!window.isSecureContext) setMidi(t('midi_insecure'),'err');
  try{ midiAccess=await navigator.requestMIDIAccess({sysex:false}); midiAccess.onstatechange=onStateChange; refreshDeviceList(true); }
  catch(err){ console.error(err); setMidi(err&&err.name==='SecurityError'?t('midi_blocked'):(err&&err.name==='NotAllowedError')?t('midi_denied'):t('midi_unavail'),'err'); }
}
function listInputs(){ return midiAccess?[...midiAccess.inputs.values()]:[]; }
function pickArturia(ins){ const c=ins.filter(i=>/microlab|arturia/i.test(i.name)); if(!c.length) return null; const g=c.filter(i=>!/daw|midiin2|control|thru/i.test(i.name)); return g[0]||c[0]; }
function refreshDeviceList(autoPick){ const sel=$('deviceSelect'), ins=listInputs(); sel.innerHTML='';
  if(!ins.length){ sel.innerHTML='<option>—</option>'; activeInputId=null; setMidi(t('midi_noinputs'),'err'); return; }
  ins.forEach(i=>{ const o=document.createElement('option'); o.value=i.id; o.textContent=i.name; sel.appendChild(o); });
  const still=activeInputId&&ins.some(i=>i.id===activeInputId);
  const remembered=!still&&savedDevice&&ins.find(i=>i.id===savedDevice);   // reconnect the device used last time
  let chosen=still?ins.find(i=>i.id===activeInputId):(remembered||((autoPick||!activeInputId)?(pickArturia(ins)||ins[0]):ins[0]));
  sel.value=chosen.id; attachInput(chosen.id);
}
function attachInput(id){ if(activeInputId&&activeInputId!==id) releaseLiveInput(); listInputs().forEach(i=>i.onmidimessage=null); const inp=listInputs().find(i=>i.id===id); if(!inp) return; inp.onmidimessage=onMidiMessage; activeInputId=id; savedDevice=id; setMidi(inp.name,'on'); saveAll(); }
function autoReconnectMidi(){ // silent reconnect when the browser already granted MIDI access
  if(!navigator.permissions||!navigator.requestMIDIAccess) return;
  try{ navigator.permissions.query({name:'midi',sysex:false}).then(p=>{ if(p.state==='granted') connectMidi(); }).catch(()=>{}); }catch(_){}
}
function onStateChange(){ const was=activeInputId, ins=listInputs(), present=activeInputId&&ins.some(i=>i.id===activeInputId); if(was&&!present){ panic(); activeInputId=null; } refreshDeviceList(false); }
function onMidiMessage(e){ const [st,d1,d2]=e.data; midiIn(st,d1,d2,'midi'); }
// One decoder for every transport (Web MIDI, Bluetooth MIDI): notes, sustain (CC64), mod wheel (CC1) and pitch bend.
function midiIn(st,d1,d2,src){ const cmd=st&0xf0;
  if(cmd===0x90&&d2>0){ handleNoteOn(d1,d2,src); audioLockCheck(); } else if(cmd===0x80||(cmd===0x90&&d2===0)) handleNoteOff(d1,src);
  else if(cmd===0xE0) setBendFromValue(((d2<<7)|d1)-8192);
  else if(cmd===0xB0){ if(d1===64){ const dn=d2>=64; if(pedalDown&&!dn) pedalUp(); pedalDown=dn; } else if(d1===1&&lfoGain&&actx) lfoGain.gain.setTargetAtTime((d2/127)*35,actx.currentTime,.03); }
}
/* ---------- BLUETOOTH MIDI: BLE-MIDI straight from the piano over Web Bluetooth ----------
   Notifications are decoded and handed to midiIn() in the same event turn: no queue, timer or polling between the radio and the
   sound. The chooser only opens from the Connect button; Reconnect (and the silent start-up reconnect) reuse a device the site was
   already allowed to use, without a chooser. */
const BLE_MIDI_SVC='03b80e5a-ede8-4b33-a751-6ce34ec4c700', BLE_MIDI_CHR='7772e5db-3868-4112-a1a9-f2669d106bf3';
const BLE={dev:null,chr:null,busy:false,want:false,gen:0,tries:0,retryT:0,guardT:0,timedOut:0,msg:null,cls:'',arg:null,saved:null,
  run:0,need:0,n:0,d1:0,skip:0,sysex:false,pedal:false,bend:false,mod:false};
function bleCan(){ return !!(navigator.bluetooth&&navigator.bluetooth.requestDevice); }
function bleLive(){ return !!(BLE.chr&&BLE.dev&&BLE.dev.gatt&&BLE.dev.gatt.connected); }
function bleName(){ return (BLE.dev&&BLE.dev.name)||(BLE.saved&&BLE.saved.name)||t('ble_dev'); }
function bleSet(key,cls,arg){ BLE.msg=key; BLE.cls=cls||''; BLE.arg=arg==null?null:arg; bleUi(); }
function bleUi(){ midiChipSync(); const st=$('set-ble-status'), b=$('set-ble'), re=$('set-ble-re'); if(!st||!b) return;
  const live=bleLive(), key=BLE.msg||(bleCan()?(BLE.dev&&!live?'ble_known':'ble_off'):'ble_unsupported');
  st.textContent=t(key,BLE.msg&&BLE.arg!=null?BLE.arg:bleName()); st.dataset.s=live?'on':(BLE.msg?BLE.cls:(bleCan()?'':'err'));
  b.textContent=t(live?'ble_disconnect':BLE.busy?'ble_cancel_btn':'ble_connect'); b.disabled=!bleCan();
  re.hidden=!(BLE.dev&&!live&&!BLE.busy); }
function bleClick(){ if(bleLive()||BLE.busy){ bleDisconnect(); return; } bleChoose(); }
async function bleChoose(){
  if(!bleCan()){ bleSet('ble_unsupported','err'); return; }
  if(!window.isSecureContext){ bleSet('ble_insecure','err'); return; }
  let req;
  try{ req=navigator.bluetooth.requestDevice({ filters:[{services:[BLE_MIDI_SVC]},...['ES120','ES110','ES520','ES920','KAWAI','Kawai'].map(namePrefix=>({namePrefix}))], optionalServices:[BLE_MIDI_SVC] }); }
  catch(err){ bleErr(err); return; }
  ensureAudio(); bleSet('ble_choose');
  let dev; try{ dev=await req; }catch(err){ bleErr(err); return; }
  BLE.tries=0; bleOpen(dev,false);
}
function bleErr(err,quiet){ const n=err&&err.name, m=String((err&&err.message)||''); console.warn('Bluetooth MIDI:',err);
  if(n==='NotFoundError'&&/cancel/i.test(m)) bleSet('ble_cancel');
  else if(n==='NotAllowedError'||/permission|denied/i.test(m)) bleSet('ble_denied','err');
  else if(n==='SecurityError'||/blocked/i.test(m)) bleSet('ble_blocked','err');
  else if(n==='NotSupportedError') bleSet('ble_unsupported','err');
  else if(/adapter|turned off|not available|unavailable/i.test(m)) bleSet('ble_adapter','err');
  else if(n==='NotFoundError'&&/service|characteristic/i.test(m)) bleSet('ble_nomidi','err');
  else if(quiet) bleSet('ble_known');
  else bleSet('ble_failed','err',n||m||'?'); }
// A superseded attempt (user pressed Disconnect, or picked another piano) closes the link it opened unless it is wanted again.
function bleStale(gen,dev){ if(gen===BLE.gen) return false; if(!BLE.want||BLE.dev!==dev){ try{ dev.gatt.disconnect(); }catch(_){} } return true; }
// retrying: an automatic reconnect after the link dropped; quiet: the silent start-up attempt (no red errors if the piano is off).
async function bleOpen(dev,retrying,quiet){
  if(BLE.busy&&BLE.dev===dev) return;
  if(BLE.dev&&BLE.dev!==dev) bleDisconnect(true);   // switching pianos: drop the old link first
  clearTimeout(BLE.retryT); BLE.dev=dev; BLE.want=true; BLE.busy=true; const gen=++BLE.gen;
  dev.removeEventListener('gattserverdisconnected',bleOnGone); dev.addEventListener('gattserverdisconnected',bleOnGone);
  if(!retrying) bleSet('ble_connecting'); else bleUi();
  // gatt.connect() can wait a long time for a piano that is off; give up after 15 s so the button never hangs.
  clearTimeout(BLE.guardT); BLE.guardT=setTimeout(()=>{ if(BLE.busy&&BLE.gen===gen){ BLE.timedOut=gen; try{ dev.gatt.disconnect(); }catch(_){} } },15000);
  try{
    const server=await dev.gatt.connect(); if(bleStale(gen,dev)) return;
    const svc=await server.getPrimaryService(BLE_MIDI_SVC), chr=await svc.getCharacteristic(BLE_MIDI_CHR); if(bleStale(gen,dev)) return;
    chr.removeEventListener('characteristicvaluechanged',bleOnValue); chr.addEventListener('characteristicvaluechanged',bleOnValue);
    bleParserReset(); BLE.chr=chr;
    await chr.startNotifications(); if(bleStale(gen,dev)){ chr.removeEventListener('characteristicvaluechanged',bleOnValue); return; }
    clearTimeout(BLE.guardT); BLE.busy=false; BLE.tries=0; BLE.saved={id:dev.id,name:dev.name||'',auto:true}; saveAll();
    bleSet('ble_on','on');
  }catch(err){
    if(gen!==BLE.gen) return;
    clearTimeout(BLE.guardT); BLE.busy=false; bleUnhook();
    if(err&&err.name==='NotFoundError'&&/service|characteristic/i.test(String(err.message||''))){ BLE.want=false; try{ dev.gatt.disconnect(); }catch(_){} bleSet('ble_nomidi','err'); return; }
    if(retrying&&BLE.want){ bleRetry(); return; }
    BLE.want=false;
    if(BLE.timedOut===gen) bleSet(quiet?'ble_known':'ble_unreach',quiet?'':'err'); else bleErr(err,quiet);
  }
}
function bleUnhook(){ if(BLE.chr) BLE.chr.removeEventListener('characteristicvaluechanged',bleOnValue); BLE.chr=null; }
function bleOnGone(e){ if(e.target!==BLE.dev) return; const was=!!BLE.chr; bleUnhook(); bleReleaseInput();
  if(BLE.busy) return;   // a connect in flight reports its own failure
  if(BLE.want&&was){ BLE.tries=0; bleRetry(); } else bleUi(); }
// After an unexpected drop, try the same device again a few times (no chooser needed), then hand over to the Reconnect button.
function bleRetry(){ const dev=BLE.dev; if(!dev||!BLE.want) return;
  if(BLE.tries>=3){ BLE.want=false; bleSet('ble_gone','err'); return; }
  const wait=[500,2000,5000][BLE.tries++]; bleSet('ble_lost','err');
  clearTimeout(BLE.retryT); BLE.retryT=setTimeout(()=>{ if(BLE.want&&BLE.dev===dev&&!bleLive()) bleOpen(dev,true); },wait); }
function bleReconnect(){ const dev=BLE.dev; if(!dev||bleLive()||BLE.busy) return; ensureAudio(); BLE.tries=0; bleOpen(dev,false); }
function bleDisconnect(keepMsg){ const chr=BLE.chr, dev=BLE.dev; BLE.want=false; BLE.gen++; BLE.busy=false; clearTimeout(BLE.retryT); clearTimeout(BLE.guardT);
  bleUnhook(); bleReleaseInput(); if(BLE.saved){ BLE.saved.auto=false; saveAll(); }
  if(chr) chr.stopNotifications().catch(()=>{});
  if(dev&&dev.gatt&&dev.gatt.connected){ try{ dev.gatt.disconnect(); }catch(_){} }
  if(!keepMsg) bleSet('ble_off'); }
// Nothing may stay stuck when the link goes: keys held over Bluetooth, its sustain pedal, bend and mod wheel are let go.
function bleReleaseInput(){ [...inputOwners.entries()].forEach(([m,o])=>{ if(o.has('ble')) handleNoteOff(m,'ble'); });
  if(BLE.pedal&&pedalDown){ pedalDown=false; pedalUp(); } if(BLE.bend) setBendFromValue(0); if(BLE.mod&&lfoGain&&actx) lfoGain.gain.setTargetAtTime(0,actx.currentTime,.03);
  BLE.pedal=BLE.bend=BLE.mod=false; bleParserReset(); }
async function bleAutoReconnect(){ const s=BLE.saved; if(!s||!bleCan()||!window.isSecureContext||!navigator.bluetooth.getDevices) return;
  try{ const dev=(await navigator.bluetooth.getDevices()).find(d=>d.id===s.id); if(!dev||BLE.dev) return; BLE.dev=dev; bleUi(); if(s.auto) bleOpen(dev,false,true); }
  catch(err){ console.warn('Bluetooth MIDI:',err); } }
function bleParserReset(){ BLE.run=0; BLE.need=0; BLE.n=0; BLE.skip=0; BLE.sysex=false; }
function bleOnValue(e){ const v=e.target.value; if(v&&v.byteLength>1) bleParse(new Uint8Array(v.buffer,v.byteOffset,v.byteLength)); }
/* BLE-MIDI packet: [header 10hhhhhh] then messages, each normally led by a timestamp byte [1lllllll]. A byte with bit 7 set that
   directly follows a timestamp is a status byte; any other byte with bit 7 set is the next timestamp. Within a packet a message may
   drop its status (running status) and then also its timestamp, so several notes can share one notification. SysEx may span
   packets (continuation packets carry only data after the header). Messages are dispatched as soon as their last byte is read;
   the timestamps carry no information we need, because the packet is played the moment it arrives. */
function bleParse(p){ if((p[0]&0xC0)!==0x80) return;
  let ts=false;
  for(let i=1;i<p.length;i++){ const b=p[i];
    if(b&0x80){ if(!ts){ ts=true; continue; } ts=false; bleStatus(b); }
    else { ts=false; bleData(b); } } }
function bleStatus(b){
  if(b>=0xF8) return;                                         // real-time (clock, active sensing…): ignored, running status kept
  if(b===0xF0){ BLE.sysex=true; BLE.run=0; BLE.n=0; return; }
  if(b===0xF7){ BLE.sysex=false; return; }
  BLE.sysex=false; BLE.n=0;
  if(b>0xF0){ BLE.run=0; BLE.skip=b===0xF2?2:(b===0xF1||b===0xF3)?1:0; return; }   // system common: skip its data, cancel running status
  BLE.run=b; BLE.skip=0; BLE.need=((b&0xF0)===0xC0||(b&0xF0)===0xD0)?1:2; }
function bleData(b){ if(BLE.sysex) return;
  if(!BLE.run){ if(BLE.skip) BLE.skip--; return; }
  if(BLE.n===0){ if(BLE.need===1){ bleMsg(BLE.run,b,0); return; } BLE.d1=b; BLE.n=1; return; }
  BLE.n=0; bleMsg(BLE.run,BLE.d1,b); }
function bleMsg(st,d1,d2){ const cmd=st&0xF0;
  if(cmd===0xB0){ if(d1===64) BLE.pedal=d2>=64; else if(d1===1) BLE.mod=d2>0; } else if(cmd===0xE0) BLE.bend=((d2<<7)|d1)!==8192;
  midiIn(st,d1,d2,'ble'); }

/* ---------- INSTALLED APP: offline copy, install prompt, full screen and screen wake lock ---------- */
const PWA={sw:'',err:'',prompt:null,installed:false};
function pwaStandalone(){ return !!((window.matchMedia&&(matchMedia('(display-mode: standalone)').matches||matchMedia('(display-mode: fullscreen)').matches))||navigator.standalone===true); }
function pwaInit(){
  window.addEventListener('beforeinstallprompt',e=>{ e.preventDefault(); PWA.prompt=e; pwaUi(); });
  window.addEventListener('appinstalled',()=>{ PWA.prompt=null; PWA.installed=true; pwaUi(); });
  if(location.protocol==='file:') PWA.sw='file';
  else if(!('serviceWorker' in navigator)) PWA.sw='unsupported';
  else if(!window.isSecureContext) PWA.sw='file';
  else {
    const killed = new URL(location.href).searchParams.get('sw-kill-switch')==='done';
    if(killed){ const clean=new URL(location.href); clean.searchParams.delete('sw-kill-switch'); history.replaceState(null,'',clean.href); PWA.sw='unsupported'; pwaUi(); return; }
    PWA.sw='pending';
    const reg=()=>navigator.serviceWorker.register('sw.js',{scope:'./',updateViaCache:'none'})
      .then(()=>navigator.serviceWorker.ready).then(()=>{ PWA.sw='ready'; pwaUi(); })
      .catch(err=>{ PWA.sw='error'; PWA.err=(err&&(err.name||err.message))||'?'; console.warn('Service worker:',err); pwaUi(); });
    if(document.readyState==='complete') reg(); else window.addEventListener('load',reg,{once:true}); }
  pwaUi(); }
function pwaUi(){ const st=$('set-pwa-status'), ib=$('set-install'); if(!st||!ib) return;
  const k=(PWA.installed||pwaStandalone())&&PWA.sw!=='file'?'pwa_installed':({file:'pwa_file',unsupported:'pwa_unsupported',ready:'pwa_ready',error:'pwa_err'})[PWA.sw]||'pwa_pending';
  st.textContent=t(k,PWA.err); st.dataset.s=PWA.sw==='error'?'err':''; ib.hidden=!PWA.prompt; }
async function pwaInstall(){ const p=PWA.prompt; if(!p) return; PWA.prompt=null; pwaUi();
  try{ await p.prompt(); const c=await p.userChoice; if(c&&c.outcome==='accepted') PWA.installed=true; }catch(err){ console.warn('Install:',err); } pwaUi(); }
function fsCan(){ return !!(document.fullscreenEnabled&&document.documentElement.requestFullscreen); }
function fsUi(){ const b=$('set-full'); if(!b) return; const row=b.closest('.set-row'); if(row) row.hidden=!fsCan(); b.textContent=t(document.fullscreenElement?'full_exit':'full_enter'); }
function fsToggle(){ if(document.fullscreenElement){ document.exitFullscreen().catch(()=>{}); return; }
  document.documentElement.requestFullscreen({navigationUI:'hide'}).catch(err=>console.warn('Full screen:',err)); }
// Screen Wake Lock: a remembered choice, held while the page is in front, given back after 30 minutes without playing or touching,
// taken again on the next note or tap. The browser drops the lock whenever the page is hidden; it is re-requested on return.
const WAKE={want:false,lock:null,busy:false,err:'',fails:0,idle:false,last:0,idleT:0,gest:false}, WAKE_IDLE_MS=30*60*1000;
function wakeCan(){ return !!(navigator.wakeLock&&navigator.wakeLock.request); }
async function wakeGet(){ if(!WAKE.want||WAKE.idle||WAKE.lock||WAKE.busy||!wakeCan()||document.visibilityState!=='visible') return;
  WAKE.busy=true;
  try{ const s=await navigator.wakeLock.request('screen'); WAKE.busy=false;
    if(!WAKE.want||WAKE.idle||document.visibilityState!=='visible'){ s.release().catch(()=>{}); wakeUi(); return; }
    WAKE.lock=s; WAKE.err=''; WAKE.fails=0; s.addEventListener('release',()=>{ if(WAKE.lock===s) WAKE.lock=null; wakeUi(); }); }
  catch(err){ WAKE.busy=false; WAKE.err=(err&&err.name)||'Error'; WAKE.fails++; if(WAKE.fails===1) console.warn('Wake lock:',err);
    if(WAKE.fails<3) wakeOnGesture(); }   // e.g. no user activation yet: one quiet retry on the next tap or key, never a loop
  wakeUi(); }
function wakeOnGesture(){ if(WAKE.gest) return; WAKE.gest=true;
  const go=()=>{ WAKE.gest=false; ['pointerdown','keydown'].forEach(ev=>window.removeEventListener(ev,go,true)); wakeGet(); };
  ['pointerdown','keydown'].forEach(ev=>window.addEventListener(ev,go,true)); }
function wakeDrop(){ const s=WAKE.lock; WAKE.lock=null; if(s) s.release().catch(()=>{}); }
function wakeSet(on){ WAKE.want=!!on; WAKE.idle=false; WAKE.err=''; WAKE.fails=0;
  if(WAKE.want){ wakePing(); wakeGet(); } else { clearTimeout(WAKE.idleT); WAKE.idleT=0; wakeDrop(); }
  saveAll(); wakeUi(); }
function wakePing(){ if(!WAKE.want) return; WAKE.last=performance.now();
  if(WAKE.idle){ WAKE.idle=false; wakeGet(); wakeUi(); }
  if(!WAKE.idleT) wakeArm(WAKE_IDLE_MS); }
function wakeArm(ms){ WAKE.idleT=setTimeout(()=>{ WAKE.idleT=0; if(!WAKE.want) return; const left=WAKE_IDLE_MS-(performance.now()-WAKE.last);
  if(left>1000){ wakeArm(left); return; } WAKE.idle=true; wakeDrop(); wakeUi(); },ms); }
function wakeUi(){ const cb=$('set-wake'), st=$('set-wake-status'); if(!cb||!st) return; const can=wakeCan(); cb.checked=WAKE.want&&can; cb.disabled=!can;
  st.textContent=!can?t('wake_unsupported'):!WAKE.want?t('wake_off'):WAKE.lock?t('wake_on'):WAKE.idle?t('wake_idle'):WAKE.err==='NotAllowedError'?t('wake_denied'):WAKE.err?t('wake_err',WAKE.err):t('wake_wait');
  st.dataset.s=WAKE.want&&WAKE.lock?'on':WAKE.want&&WAKE.err?'err':''; }
function wakeInit(){
  ['pointerdown','keydown'].forEach(ev=>window.addEventListener(ev,wakePing,{capture:true,passive:true}));
  document.addEventListener('visibilitychange',()=>{ if(document.visibilityState==='visible'&&WAKE.want){ WAKE.fails=0; wakePing(); wakeGet(); } wakeUi(); });
  if(WAKE.want){ wakePing(); wakeGet(); } wakeUi(); }
/* computer keyboard */
// Notes and Z / X follow physical key positions (KeyboardEvent.code), so QWERTZ, AZERTY… keep the piano shape; shortcuts stay on letters.
const KEYMAP={KeyA:0,KeyW:1,KeyS:2,KeyE:3,KeyD:4,KeyF:5,KeyT:6,KeyG:7,KeyY:8,KeyH:9,KeyU:10,KeyJ:11,KeyK:12}; const typingDown=new Map();
function shiftTypeOctave(dir){ releaseTypingKeys(); const next=typeOctave+dir*12, minLow=BASE_LOW, maxLow=Math.max(BASE_LOW,BASE_HIGH-view.oct*12); if(dir<0){ if(next<view.low&&view.low>minLow){ view.low=Math.max(minLow,view.low-12); buildKeyboard(); repaintHeld(); } } else if(dir>0){ if(next+12>viewHigh()&&view.low<maxLow){ view.low=Math.min(maxLow,view.low+12); buildKeyboard(); repaintHeld(); } } typeOctave=next; clampTypeOctave(); }
function physKey(e){ return e.code||(/^[a-z]$/i.test(e.key||'')?'Key'+e.key.toUpperCase():''); }   // some synthetic and virtual-keyboard events carry no code
// Name those physical keys as the user's layout prints them (Keyboard Map API, Chromium); elsewhere the QWERTY names stay.
function kbdLayoutLabels(){ const kb=navigator.keyboard; if(!kb||typeof kb.getLayoutMap!=='function') return;
  try{ kb.getLayoutMap().then(map=>document.querySelectorAll('kbd[data-codes]').forEach(el=>{ const ks=el.dataset.codes.split(' ').map(c=>map.get(c));
    if(ks.every(x=>typeof x==='string'&&x.trim())) el.textContent=ks.map(x=>x.toUpperCase()).join(el.dataset.sep||' '); })).catch(()=>{}); }catch(_){} }
function releaseTypingKeys(){ typingDown.forEach((m,k)=>handleNoteOff(m,'typing:'+k)); typingDown.clear(); }
function inField(){ const a=document.activeElement; return a&&(/^(INPUT|SELECT|TEXTAREA)$/.test(a.tagName)||a.isContentEditable); }
document.addEventListener('keydown',e=>{ if(e.metaKey||e.ctrlKey||e.altKey||e.key==='Meta'||e.key==='Control'||e.key==='Alt'){ releaseTypingKeys(); return; } if(inField()||$('drawer').classList.contains('on')||$('helpBox').classList.contains('on')||e.repeat) return; const k=e.key.toLowerCase();
  if(e.key==='?'){ e.preventDefault(); openHelp(!$('helpBox').classList.contains('on')); return; }
  if(rdKey(e,k)) return;
  if(SES.active&&SES.q){ // session shortcuts: digits pick an answer, R replays, N advances
    if(/^[1-9]$/.test(k)&&!SES.answered&&SES.q.mode==='ear'){ const b=$('q-answers').children[+k-1]; if(b){ e.preventDefault(); b.click(); return; } }
    if(k==='r'&&!$('q-replay').hidden){ e.preventDefault(); $('q-replay').click(); return; }
    if(k==='n'&&!$('q-next').hidden){ e.preventDefault(); $('q-next').click(); return; }
  }
  if(view0()==='analysis'&&AN.notes.length&&/^[lpmc]$/.test(k)) return;   // score shortcuts keep their letters wherever the layout puts them
  const c=physKey(e);
  if(c==='KeyZ'){ e.preventDefault(); shiftTypeOctave(-1); return; } if(c==='KeyX'){ e.preventDefault(); shiftTypeOctave(1); return; } if(c in KEYMAP){ const m=typeOctave+KEYMAP[c]; if(!typingDown.has(c)){ e.preventDefault(); typingDown.set(c,m); handleNoteOn(m,100,'typing:'+c); } } });
document.addEventListener('keyup',e=>{ const c=physKey(e); if(typingDown.has(c)){ const m=typingDown.get(c); typingDown.delete(c); handleNoteOff(m,'typing:'+c); } });

/* ---------- GRADING CORE ---------- */
function chordTargetPcs(rootPc,tpl){ return [...new Set(tpl.intervals.map(i=>((i+rootPc)%12+12)%12))].sort((a,b)=>a-b); }
function inversionOf(rootPc,tpl,bassMidi){ const bi=((pc(bassMidi)-rootPc)%12+12)%12, i=tpl.pcset.indexOf(bi); return i<0?0:i; }
function identifyChord(notes,expected){ const pcs=[...new Set(notes.map(pc))].sort((a,b)=>a-b); if(pcs.length<3) return null; const bassPc=pc(Math.min(...notes)), cands=[];
  for(const c of CHORDS){ if(c.pcset.length!==pcs.length) continue; for(let r=0;r<12;r++){ const cand=[...new Set(pcs.map(p=>((p-r)%12+12)%12))].sort((a,b)=>a-b); if(setEq(cand,c.pcset)){ const inv=c.pcset.indexOf(((bassPc-r)%12+12)%12); cands.push({rootPc:r,chord:c,inversion:inv<0?0:inv,bassPc}); } } }
  if(!cands.length) return null;
  cands.sort((a,b)=>{ if(expected!=null){ const ae=a.rootPc===expected?0:1,be=b.rootPc===expected?0:1; if(ae!==be) return ae-be; } const ar=a.inversion===0?0:1,br=b.inversion===0?0:1; if(ar!==br) return ar-br; if(a.inversion!==b.inversion) return a.inversion-b.inversion; return a.chord.idx-b.chord.idx; });
  return cands[0]; }
function slashLabel(id){ return rootName(id.rootPc)+id.chord.symbol+(id.inversion>0?'/'+rootName(id.bassPc):''); }
function romanFor(keyRoot,id){ if(!id||keyRoot<0) return ''; const rel=((id.rootPc-keyRoot)%12+12)%12; let deg=MAJOR.indexOf(rel),acc=''; if(deg<0){ deg=MAJOR.indexOf((rel+11)%12); if(deg>=0)acc='♯'; else { deg=MAJOR.indexOf((rel+1)%12); if(deg>=0)acc='♭'; } } if(deg<0) return ''; let num=ROMAN[deg]; const s=id.chord.symbol; if(/^m(?!aj)/.test(s)||s.startsWith('dim')) num=num.toLowerCase(); let suf=''; if(/dim/.test(s)||s==='m7♭5') suf='°'; else if(/aug|♯5/.test(s)) suf='+'; if(id.chord.pcset.includes(10)||id.chord.pcset.includes(11)) suf+='⁷'; return acc+num+suf; }

/* ============================================================================
   ITEM MODEL + SPACED REPETITION
   ============================================================================ */
const INTRO_IV=[7,5,4,3,12,2,9,8,11,10,1,6];
const INTRO_CH=['maj','m','dim','sus4','sus2','aug','maj7','7','m7','6','m6','m7♭5','dim7','mMaj7','add9','9','maj9','m9','7♯5','7♭5','maj7♯11','7♭9','7♯9','11','13'];
const INTRO_SC=['Major (Ionian)','Aeolian (Natural minor)','Major pentatonic','Minor pentatonic','Dorian','Mixolydian','Blues','Lydian','Phrygian','Harmonic minor','Melodic minor','Locrian','Harmonic major','Whole tone','Phrygian dominant','Hungarian minor','Diminished (W-H)','Diminished (H-W)','Chromatic'];
const CATS={ interval:{label:'Intervals'}, chord:{label:'Chords'}, scale:{label:'Scales'}, prog:{label:'Progressions'} };
const ITEMS=[]; const ITEM_BY_ID={};
INTRO_IV.forEach((semi,i)=>{ const iv=INTERVALS.find(x=>x.semi===semi); ITEMS.push({id:'iv:'+semi,cat:'interval',semi,label:iv.name,short:iv.short,intro:i}); });
INTRO_CH.forEach((sym,i)=>{ const c=CHORDS.find(x=>x.symbol===sym); if(c) ITEMS.push({id:'ch:'+sym,cat:'chord',ref:c,label:c.name,short:sym,intro:100+i}); });
INTRO_SC.forEach((nm,i)=>{ if(SCALES[nm]) ITEMS.push({id:'sc:'+nm,cat:'scale',name:nm,label:nm,short:nm,intro:200+i}); });
PROGS.forEach((p,i)=>{ ITEMS.push({id:'pr:'+p.name,cat:'prog',ref:p,label:p.name,short:p.name,intro:300+i}); });
ITEMS.forEach(it=>ITEM_BY_ID[it.id]=it);

function freshData(){ return { srs:{}, streak:0, bestStreak:0, lastActive:0, todayDay:0, todayCount:0, newToday:0, totalReviews:0, totalCorrect:0, placed:false, history:{}, singCleared:{}, sheet:{}, settings:{ goal:12, newPerDay:5, allowInv:false, metronome:false, drone:false } }; }
let data = freshData();
function currentStreak(){ return (data.lastActive>=todayN()-1) ? (data.streak||0) : 0; }   // a missed day shows as 0, not the stale count
function srsOf(id){ return data.srs[id] || (data.srs[id]={box:0,ease:2.3,due:0,reps:0,lapses:0,last:0}); }
const IVL=[0,1,2,4,9,21,45,90];
function reviewItem(id,correct){
  const it=srsOf(id); it.reps++;
  if(correct){ it.box=Math.min(7,it.box+1); it.ease=Math.min(2.9,it.ease+.05); }
  else { it.box=1; it.lapses++; it.ease=Math.max(1.6,it.ease-.2); }
  const days=IVL[it.box]!==undefined?IVL[it.box]:120;
  it.due=todayN()+Math.max(0,Math.round(days*(it.ease/2.3))); it.last=todayN();
  data.totalReviews++; if(correct) data.totalCorrect++;
  touchDay();
  if(it.reps===1) data.newToday=(data.newToday||0)+1;   // count fresh concepts against the daily quota
  saveAll();
}
function touchDay(){ const t=todayN();
  if(data.todayDay!==t){ if(data.lastActive===t-1) data.streak++; else data.streak=1; data.todayDay=t; data.todayCount=0; data.newToday=0; data.lastActive=t; }
  data.todayCount++;
  data.bestStreak=Math.max(data.bestStreak||0,data.streak||0);
  const h=data.history||(data.history={}); h[t]=(h[t]||0)+1;
  const keys=Object.keys(h); if(keys.length>400) keys.sort((a,b)=>a-b).slice(0,keys.length-400).forEach(k=>delete h[k]);
}
function seedPlacement(id,known){ if(known){ const it=srsOf(id); it.box=4; it.ease=2.4; it.reps=1; it.lapses=0; it.due=todayN()+Math.round(IVL[4]*(it.ease/2.3)); it.last=todayN(); } data.totalReviews++; if(known) data.totalCorrect++; touchDay(); saveAll(); }
const SCALE_EAR_POOL=['Major (Ionian)','Aeolian (Natural minor)','Dorian','Mixolydian','Phrygian','Lydian','Major pentatonic','Minor pentatonic','Blues','Harmonic minor','Whole tone'];
function scaleEarOptions(correct){ let pool=SCALE_EAR_POOL.filter(n=>n!==correct); pool=shuffle(pool).slice(0,6); pool.push(correct); return shuffle(pool); }
function chordEarOptions(correctItem){ // prefer confusable distractors: chords with the same number of notes
  const others=ITEMS.filter(x=>x.cat==='chord'&&x.short!==correctItem.short);
  const same=shuffle(others.filter(x=>x.ref.pcset.length===correctItem.ref.pcset.length));
  const rest=shuffle(others.filter(x=>x.ref.pcset.length!==correctItem.ref.pcset.length));
  return shuffle(same.concat(rest).slice(0,7).concat([correctItem]));
}
const PLACEMENT=['iv:7','iv:5','iv:4','iv:3','iv:12','ch:maj','ch:m','ch:maj7','ch:7','sc:Major (Ionian)','sc:Aeolian (Natural minor)','pr:I–IV–V'];
function boxOf(id){ return data.srs[id]?data.srs[id].box:0; }
function isDue(id){ const s=data.srs[id]; return s&&s.reps>0&&s.due<=todayN(); }
function isNew(id){ const s=data.srs[id]; return !s||s.reps===0; }
function dueItems(){ return ITEMS.filter(it=>isDue(it.id)).sort((a,b)=>data.srs[a.id].due-data.srs[b.id].due); }
function newItemsAvail(){ return ITEMS.filter(it=>isNew(it.id)).sort((a,b)=>a.intro-b.intro); }
// New concepts still allowed today: the daily quota minus those already introduced today (across sessions).
function newQuotaLeft(){ const introduced=data.todayDay===todayN()?(data.newToday||0):0; return Math.max(0, data.settings.newPerDay-introduced); }
function masteredCount(){ return ITEMS.filter(it=>boxOf(it.id)>=4).length; }

/* ============================================================================
   SESSION ENGINE  (interleaved, adaptive, with feedback + elaboration)
   ============================================================================ */
const SES={ active:false, queue:[], idx:0, correct:0, total:0, q:null, answered:false, targeted:null, placement:false, promptT:0 };
function sesStopPrompt(){ clearTimeout(SES.promptT); SES.promptT=0; }
function sesPrompt(q,play){ sesStopPrompt(); SES.promptT=setTimeout(()=>{ SES.promptT=0; if(SES.active&&SES.q===q&&!SES.answered) play(); },250); }
function buildQueue(){
  const goal=data.settings.goal;
  const due=dueItems();
  const fresh=newItemsAvail().slice(0, newQuotaLeft());
  let pool=[...due];
  for(const f of fresh){ if(pool.length>=goal) break; pool.push(f); }
  if(pool.length<goal){ // top up with the weakest seen items for extra retrieval practice
    const weak=ITEMS.filter(it=>!isNew(it.id)&&!isDue(it.id)).sort((a,b)=>boxOf(a.id)-boxOf(b.id));
    for(const w of weak){ if(pool.length>=goal) break; if(!pool.includes(w)) pool.push(w); }
  }
  if(pool.length<goal && ITEMS.filter(it=>!isNew(it.id)).length<goal){ // early days only: introduce extra new concepts so the session feels substantial
    for(const m of newItemsAvail()){ if(pool.length>=goal) break; if(!pool.includes(m)) pool.push(m); }
  }
  if(!pool.length) pool=shuffle(ITEMS).slice(0,goal);
  let qs=shuffle(pool).map(makeQuestion);
  // interleave: avoid two same-category in a row when possible
  for(let i=1;i<qs.length;i++){ if(qs[i].it.cat===qs[i-1].it.cat){ const j=qs.findIndex((q,k)=>k>i&&q.it.cat!==qs[i-1].it.cat); if(j>-1){ [qs[i],qs[j]]=[qs[j],qs[i]]; } } }
  return qs;
}
function makeQuestion(it){
  const b=boxOf(it.id);
  const forced = SES.targeted && SES.targeted.mode;
  let mode;
  if(SES.placement) mode='ear';            // placement probes real by-ear knowledge
  else if(forced) mode=forced;             // targeted practice honours the chosen mode
  else if(it.cat==='scale'||it.cat==='prog') mode = b>=3?'ear':'play';
  else mode = b>=2 ? 'ear' : 'play';      // desirable difficulty: recall-by-sound once recognised-by-doing
  let key;
  if(SES.targeted && SES.targeted.key!=null && SES.targeted.key!=='all') key=(+SES.targeted.key)||0;   // honour the key picked in Practice
  else key = b<1 ? randItem([0,7,5,2,9]) : Math.floor(Math.random()*12);   // start in friendly keys
  return { it, mode, key, idx:0, anchor:null, missed:false, hinted:false };
}
function startSession(targeted){
  ensureAudio();
  sesStopPrompt();
  SES.targeted=targeted||null; SES.placement=false;
  SES.queue = targeted ? Array.from({length:9999}) : buildQueue();   // targeted = endless
  SES.idx=0; SES.correct=0; SES.total=0; SES.active=true;
  openSessionUI();
  nextQuestion();
}
function startPlacement(){
  ensureAudio();
  sesStopPrompt();
  SES.targeted=null; SES.placement=true;
  SES.queue = PLACEMENT.map(id=>ITEM_BY_ID[id]).filter(Boolean).map(makeQuestion);
  SES.idx=0; SES.correct=0; SES.total=0; SES.active=true;
  openSessionUI();
  nextQuestion();
}
function sesHome(){ return SES.targeted?'practice':'today'; }
function openSessionUI(){ const ses=$('session');
  if(SES.targeted){ $('view-practice').appendChild(ses); $('pr-home').style.display='none'; }
  else { $('view-today').insertBefore(ses,$('summary')); $('pr-home').style.display=''; }
  $('today-home').style.display='none'; $('summary').style.display='none'; ses.style.display='block'; ses.classList.add('on'); dockSync(); reflowKeys();
  requestAnimationFrame(()=>{ if(SES.active) ses.scrollIntoView({block:'start',behavior:'instant'}); }); }
function endSession(toSummary){
  const wasPlacement=SES.placement;
  if(wasPlacement){ data.placed=true; saveAll(); }
  sesStopPrompt(); ekStop(SES.q); SES.active=false; SES.placement=false; $('session').style.display='none'; $('session').classList.remove('on'); kbClearAll();
  held.forEach(m=>audioNoteOff(m)); held.clear(); heldOrder.length=0; stopMetro(); stopDrone();
  if(SES.targeted){ prRecordDrill(); $('pr-home').style.display=''; renderPracticeLast(); if(toSummary) $('pr-start').focus(); return; }
  if(toSummary) showSummary(wasPlacement); else { $('today-home').style.display='block'; refreshToday(); }
}
function nextQuestion(){
  if(!SES.targeted && SES.idx>=SES.queue.length){ endSession(true); return; }
  sesStopPrompt(); ekStop(SES.q); kbClearAll(); SES.answered=false;
  const q = SES.targeted ? makeQuestion(pickTargetedItem()) : SES.queue[SES.idx];
  SES.q=q;
  $('ses-progress').style.width = SES.targeted? '0%' : (100*SES.idx/SES.queue.length)+'%';
  $('ses-count').textContent = SES.targeted ? ('#'+(SES.total+1)+(SES.total?' · '+SES.correct+'/'+SES.total+' ✓':'')) : ((SES.idx+1)+'/'+SES.queue.length);
  $('q-verdict').textContent=''; $('q-verdict').className='verdict'; $('q-elab').textContent=''; $('q-elab').classList.remove('show');
  $('q-next').hidden=true; $('q-reveal').hidden=false; $('q-answers').hidden=true; $('q-answers').innerHTML='';
  presentQuestion(q);
}
function pickTargetedItem(){ const c=SES.targeted.cat; const pool=c==='melody'?ITEMS.filter(it=>it.cat==='scale'&&EK_MEL_SCALES.includes(it.name)):ITEMS.filter(it=>it.cat===c); // weakness-weighted
  const w=pool.map(it=>{ const s=data.srs[it.id]||{box:0}; return 1/(1+s.box); }); let tot=w.reduce((a,b)=>a+b,0),r=Math.random()*tot; for(let i=0;i<pool.length;i++){ r-=w[i]; if(r<=0) return pool[i]; } return pool[0]; }

function presentQuestion(q){
  const it=q.it; $('q-cat').textContent=catLabel(it.cat);
  const playLbl={interval:t('play_interval'),chord:t('play_chord'),scale:t('play_scale'),prog:t('play_prog')};
  $('q-mode').textContent = q.mode==='ear' ? t(ekWanted(q)?'ek_mode':'listen_answer') : playLbl[it.cat];
  $('q-replay').hidden = q.mode!=='ear';
  ekToggleSync(q);
  if(q.mode==='ear'){ presentEar(q); }
  else { presentPlay(q); }
}
function earRoot(q){ return 57+ (q.key%12 <=5 ? q.key : q.key-12) + 5; }   // mid register, kept playable

function presentPlay(q){
  const it=q.it;
  if(it.cat==='interval'){ $('q-prompt').innerHTML=ivName(it.semi)+' <span class="sub">'+t('above')+' '+rootName(q.key)+'</span>'; }
  else if(it.cat==='chord'){ $('q-prompt').innerHTML=rootName(q.key)+dispSym(it.short)+' <span class="sub">'+chordDisp(it.ref)+'</span>'; }
  else if(it.cat==='scale'){ q.offs=SCALES[it.name].concat([12]); q.anchor=null; q.idx=0; $('q-prompt').innerHTML=rootName(q.key)+' '+scaleDisp(it.name)+' <span class="sub">'+t('ascending')+'</span>'; if(data.settings.metronome) startMetro(); if(data.settings.drone) startDrone(q.key); }
  else if(it.cat==='prog'){ q.idx=0; const chain=it.ref.chords.map(ch=>rootName((q.key+ch[0])%12)+dispSym(ch[1])).join('  ·  '); $('q-prompt').innerHTML=it.ref.name+' <span class="sub">'+t('in_key')+' '+rootName(q.key)+'</span>'; $('q-verdict').className='verdict neutral'; $('q-verdict').textContent=chain; showProgTarget(q); }
}
function presentEar(q){
  ekStop(q); q.ek=null; ekUiReset();
  if(ekWanted(q)){ presentEarKeys(q); return; }
  const it=q.it; $('q-prompt').textContent=t('listen'); $('q-answers').hidden=false; const box=$('q-answers'); box.innerHTML='';
  let opts=[];
  if(it.cat==='interval'){ opts=INTERVALS.map(iv=>({k:iv.semi,t:iv.short+' · '+ivName(iv.semi)})); sesPrompt(q,()=>playInterval(earRoot(q),it.semi,'both')); }
  else if(it.cat==='chord'){ opts=chordEarOptions(it).map(x=>({k:x.short,t:x.short+' · '+chordDisp(x.ref)})); sesPrompt(q,()=>playChordMidis(it.ref.intervals.map(i=>57+q.key+i),true)); }
  else if(it.cat==='scale'){ opts=scaleEarOptions(it.name).map(nm=>({k:nm,t:scaleDisp(nm)})); sesPrompt(q,()=>playScaleNotes(60+q.key,SCALES[it.name],true)); }
  else if(it.cat==='prog'){ opts=PROGS.map(p=>({k:p.name,t:p.name})); sesPrompt(q,()=>playProg(q.key,it.ref)); }
  opts.forEach(o=>{ const b=document.createElement('button'); b.className='chip'; b.dataset.k=String(o.k); b.textContent=o.t; b.onclick=()=>answerEar(q,o.k,b); box.appendChild(b); });
}
function playProg(rootPc,prog){ ensureAudio(); stopPreviews(); const t=actx.currentTime; prog.chords.forEach((ch,i)=>{ const root=60+((rootPc+ch[0])%12), tpl=progChordTpl(ch[1]); tpl.intervals.forEach(iv=>previewNote(root+iv,t+i*.9,.8)); }); }
function showProgTarget(q){ kbClear('target'); const ch=q.it.ref.chords[q.idx], root=60+((q.key+ch[0])%12), tpl=progChordTpl(ch[1]); tpl.intervals.forEach(iv=>kbState(root+iv,'target',true)); }
function playQuestionSound(q){ const it=q.it;
  if(q.ek){ if(SES.answered) ekSound(q); else ekPlay(q); return; }
  if(it.cat==='interval') playInterval(earRoot(q),it.semi,'both');
  else if(it.cat==='chord') playChordMidis(it.ref.intervals.map(i=>57+q.key+i),true);
  else if(it.cat==='scale') playScaleNotes(60+q.key,SCALES[it.name],true);
  else if(it.cat==='prog') playProg(q.key,it.ref);
}

function answerEar(q,k,btn){ if(SES.answered) return; const it=q.it; let ok;
  if(it.cat==='interval') ok=k===it.semi;
  else if(it.cat==='chord') ok=k===it.short;
  else if(it.cat==='scale') ok=k===it.name;
  else ok=k===it.ref.name;
  if(ok){ btn.classList.add('correct'); resolve(q,true); }
  else { btn.classList.add('wrong'); q.missed=true; markEarCorrect(q); resolve(q,false); }
}
function markEarCorrect(q){ const it=q.it; const key=it.cat==='interval'?String(it.semi):it.cat==='chord'?it.short:it.cat==='scale'?it.name:it.ref.name; [...$('q-answers').children].forEach(b=>{ if(b.dataset.k===key) b.classList.add('correct'); }); }

/* ---------- BY EAR, ON THE KEYS: hear it, then play it back (intervals, chords in any inversion, short tonal melodies) ----------
   The prompt plays first; notes that arrive before it ends are ignored (armAt), so nothing the listener does while it sounds is
   graded. Octave policy: the start note may be played in any octave and everything after it is measured from it, so an interval
   keeps its exact size, a melody keeps its exact shape, and a chord keeps its pitch classes with the written lowest note.
   A wrong attempt is a lapse for the schedule but can be retried (up to EK_TRIES) after listening again. */
const EK_TRIES=3, EK_MEL_SCALES=['Major (Ionian)','Aeolian (Natural minor)','Harmonic minor','Major pentatonic','Minor pentatonic'];
const EK_CHORD_GAP=300;   // ms: a key joins the chord if another chord key is still down or it lands this close to the previous one
function ekForced(){ return !!(SES.targeted&&SES.targeted.cat==='melody'); }
function ekWanted(q){ return !!q&&q.mode==='ear'&&!SES.placement&&q.it.cat!=='prog'&&(ekForced()||!!data.settings.earKeys); }
// Spell like the key: minor-flavoured chords and scales on D, G, C, F, B♭, E♭ use flats, as do the flat major keys and the flat intervals.
function ekFlat(q){ const it=q.it, set=it.cat==='chord'?it.ref.pcset:it.cat==='scale'?SCALES[it.name]:null;
  if(set&&set.includes(3)&&!set.includes(4)) return [0,2,3,5,7,10].includes(q.key);
  return isFlatKey(q.key)||(it.cat==='interval'&&[1,3,8,10].includes(it.semi)); }
function ekName(q,m){ return noteName(m,ekFlat(q)); }
function ekToggleSync(q){ const box=$('q-ansmode'); box.hidden=!(q&&q.mode==='ear'&&!SES.placement&&q.it.cat!=='prog'&&!ekForced());
  box.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',(b.dataset.v==='keys')===!!data.settings.earKeys?'true':'false')); }
function ekUiReset(){ $('q-ekhint').textContent=''; $('q-ekprog').innerHTML=''; $('q-ekreset').hidden=true; }
function ekStop(q){ if(q&&q.ek) clearTimeout(q.ek.goT); }
function ekBuild(q){ const it=q.it;
  if(it.cat==='interval'){ const r=earRoot(q); return {kind:'iv',target:[r,r+it.semi],n:2}; }
  if(it.cat==='chord'){ const ivs=[...new Set(it.ref.intervals)].sort((a,b)=>a-b), n=ivs.length;
    const inv=n<=4&&Math.random()<.6?1+Math.floor(Math.random()*(n-1)):0;   // triads and sevenths come in every inversion
    let ns=ivs.map(i=>48+q.key+i); for(let k=0;k<inv;k++) ns.push(ns.shift()+12);
    if(ns[0]<52) ns=ns.map(m=>m+12); if(ns[ns.length-1]>88) ns=ns.map(m=>m-12);
    const pcs=[...new Set(ns.map(pc))].sort((a,b)=>a-b); return {kind:'ch',target:ns,inv,pcs,n:pcs.length}; }
  // a short tonal melody in the item's scale: starts on the tonic, moves mostly by step, ends on a stable degree
  const offs=SCALES[it.name], N=offs.length, ton=60+(q.key<=5?q.key:q.key-12), len=3+Math.floor(Math.random()*3);
  const at=d=>ton+offs[((d%N)+N)%N]+12*Math.floor(d/N), stable=d=>[0,3,4,7].includes(pc(at(d)-ton));
  let d=0; const ds=[0];
  for(let i=1;i<len;i++){ const last=i===len-1, opts=[];
    [-2,-1,1,2].forEach(s=>{ const nd=d+s; if(nd<-2||nd>N+2||(last&&!stable(nd))) return; opts.push(nd); if(Math.abs(s)===1) opts.push(nd,nd); });
    if(!opts.length) opts.push(Math.abs(d)<=Math.abs(N-d)?0:N);
    d=randItem(opts); ds.push(d); }
  const target=ds.map(at); return {kind:'mel',target,n:target.length}; }
function presentEarKeys(q){ const it=q.it, ek=q.ek=Object.assign(ekBuild(q),{tries:0,seq:[],off:0,armAt:Infinity,goT:0,won:false,warned:false});
  $('q-answers').hidden=true; $('q-answers').innerHTML='';
  const st=ekName(q,ek.target[0]), sub=ek.kind==='iv'?t('ek_sub_start',st):ek.kind==='ch'?t('ek_sub_bass',st,ek.n):t('ek_sub_mel',rootName(q.key)+' '+scaleDisp(it.name),ek.n);
  $('q-prompt').innerHTML=t('ek_p_'+ek.kind)+' <span class="sub">'+sub+'</span>';
  if(ek.kind==='mel') $('q-cat').textContent=t('ek_cat_mel');
  $('q-ekhint').textContent=t('ek_hint_'+ek.kind); $('q-ekreset').hidden=false; ekProg(q,0);
  ekPlay(q); }
// Plays the prompt and returns when (seconds after now) its last note starts.
function ekSound(q){ const ek=q.ek; ensureAudio(); if(!actx) return 0; stopPreviews(); const t0=actx.currentTime+.25, ms=ek.target; let last;
  if(ek.kind==='iv'){ previewNote(ms[0],t0,.45); previewNote(ms[1],t0+.5,.45); previewNote(ms[0],t0+1.15,.8); previewNote(ms[1],t0+1.15,.8); last=1.15; }
  else if(ek.kind==='ch'){ ms.forEach((m,i)=>previewNote(m,t0+i*.16,.4)); const bt=ms.length*.16+.1; ms.forEach(m=>previewNote(m,t0+bt,1.1)); previewNote(ms[0],t0+bt+1.35,.6); last=bt+1.35; }
  else { previewNote(ms[0],t0,.5); ms.forEach((m,i)=>previewNote(m,t0+.85+i*.5,.45)); last=.85+(ms.length-1)*.5; }
  return .25+last; }
function ekPlay(q){ const ek=q.ek; if(!ek||SES.answered) return; const wait=(ekSound(q)+.3)*1000;
  ek.armAt=performance.now()+wait; ek.seq=[]; ek.warned=false; clearTimeout(ek.goT);
  kbClear('good'); kbClear('bad'); kbClear('target'); kbState(ek.target[0],'target',true); ekProg(q,0); neutral(t('ek_listen'));
  ek.goT=setTimeout(()=>{ if(SES.q===q&&!SES.answered&&!ek.seq.length) neutral(t('ek_go')); },wait); }
function ekProg(q,k){ const ek=q.ek; $('q-ekprog').innerHTML=ek?Array.from({length:ek.n},(_,i)=>'<i'+(i<k?' class="on"':'')+'></i>').join(''):''; }
function ekFlash(ms,s){ ms.forEach(m=>kbState(m,s,true)); }
function ekOn(q,m){ const ek=q.ek; if(m==null) return; const now=performance.now();
  if(now<ek.armAt){ if(!ek.warned){ ek.warned=true; neutral(t('ek_wait')); } return; }
  if(ek.kind==='mel'){ ekMel(q,m); return; }
  if(ek.kind==='ch'){ const prev=ek.seq[ek.seq.length-1]; if(prev&&!ek.seq.some(x=>held.has(x.m)&&x.m!==m)&&now-prev.t>EK_CHORD_GAP) ek.seq=[]; }
  ek.seq.push({m,t:now}); scheduleEval(()=>ek.kind==='iv'?ekIv(q):ekCh(q),ek.kind==='iv'?90:140); }
function ekOff(q,m){ const ek=q.ek; if(!ek||SES.answered||ek.kind!=='ch'||!ek.seq.length) return; scheduleEval(()=>ekCh(q),140); }
function ekIv(q){ const ek=q.ek; if(SES.answered||SES.q!==q||!ek.seq.length) return; const s=ek.seq, start=ek.target[0], semi=ek.target[1]-start;
  let a=s[0], b=s[1];
  if(b&&Math.abs(b.t-a.t)<=80&&b.m<a.m){ const x=a; a=b; b=x; }          // struck together: the lower note is the start
  if(pc(a.m)!==pc(start)){ ekFlash([a.m],'bad'); setTimeout(()=>{ kbClear('bad'); if(SES.q===q&&!SES.answered) kbState(start,'target',true); },420); ek.seq=[]; ekProg(q,0); neutral(t('ek_start_on',ekName(q,start))); return; }
  if(!b){ ekProg(q,1); neutral(t('ek_progress',1,2)); return; }
  if(b.m===a.m){ ek.seq=[a]; return; }
  if(b.m-a.m===semi){ ekWin(q,[a.m,b.m]); return; }
  ekMiss(q,[b.m],b.m<a.m?t('ek_wrong_down'):t('ek_wrong_iv',intervalLabel(b.m-a.m))); }
function ekCh(q){ const ek=q.ek; if(SES.answered||SES.q!==q||!ek.seq.length) return;
  const ms=[...new Set(ek.seq.map(x=>x.m))].sort((a,b)=>a-b), pcs=[...new Set(ms.map(pc))].sort((a,b)=>a-b), down=ms.some(m=>held.has(m));
  if(setEq(pcs,ek.pcs)){ if(pc(ms[0])===pc(ek.target[0])) ekWin(q,ms); else ekMiss(q,[ms[0]],t('ek_wrong_inv',ekName(q,ek.target[0]))); return; }
  if(!isSubset(pcs,ek.pcs)){ ekMiss(q,ms.filter(m=>!ek.pcs.includes(pc(m))),t('ek_wrong_ch')); return; }
  ekProg(q,pcs.length);
  if(down) neutral(t('ek_keep',pcs.length,ek.n)); else { ek.seq=[]; ekProg(q,0); neutral(t('ek_hold')); } }
function ekMel(q,m){ const ek=q.ek, tg=ek.target, i=ek.seq.length;
  if(i===0){ if(pc(m)!==pc(tg[0])){ ekFlash([m],'bad'); setTimeout(()=>{ kbClear('bad'); if(SES.q===q&&!SES.answered) kbState(tg[0],'target',true); },420); neutral(t('ek_start_on',ekName(q,tg[0]))); return; } ek.off=m-tg[0]; }
  const want=tg[i]+ek.off;
  if(m!==want){ ekMiss(q,[m],t('ek_wrong_mel',i+1,t(m>want?'ek_high':'ek_low'))); return; }
  ek.seq.push({m,t:performance.now()}); kbState(m,'good',true); ekProg(q,ek.seq.length);
  if(ek.seq.length>=tg.length) ekWin(q,ek.seq.map(x=>x.m)); else neutral(t('ek_progress',ek.seq.length,tg.length)); }
function ekWin(q,ms){ q.ek.won=true; q.ek.played=ms; kbClear('target'); ekFlash(ms,'good'); ekProg(q,q.ek.n); resolve(q,true); }
function ekMiss(q,bad,msg){ const ek=q.ek; q.missed=true; ek.tries++; ek.seq=[];
  kbClear('good'); ekFlash(bad,'bad');
  if(ek.tries>=EK_TRIES){ resolve(q,false); return; }
  setTimeout(()=>{ kbClear('bad'); if(SES.q===q&&!SES.answered) kbState(ek.target[0],'target',true); },500);
  ekProg(q,0); const v=$('q-verdict'); v.className='verdict bad'; v.textContent=msg+' '+t(ek.tries===EK_TRIES-1?'ek_last':'ek_again'); }
function ekReset(){ const q=SES.q; if(!q||!q.ek||SES.answered) return; q.ek.seq=[]; kbClear('good'); kbClear('bad'); kbState(q.ek.target[0],'target',true); ekProg(q,0); neutral(t('ek_reset_msg')); }
function ekElab(q){ const ek=q.ek, names=ms=>ms.map(m=>ekName(q,m)).join(' ');
  if(ek.kind==='iv') return t('ek_el_iv',ekName(q,ek.target[0]))+' · '+names(ek.target);
  if(ek.kind==='ch') return t('ek_el_ch',invName(ek.inv),names(ek.target));
  return t('ek_el_mel',names(ek.target)); }

/* play-mode grading via held notes */
function sesInput(midi){ const q=SES.q; if(!q||SES.answered) return; if(q.ek){ ekOn(q,midi); return; } if(q.mode!=='play') return;
  if(q.it.cat==='interval') scheduleEval(()=>gradeInterval(q),200);
  else if(q.it.cat==='chord') scheduleEval(()=>gradeChord(q),300);
  else if(q.it.cat==='scale') gradeScaleNote(q,[...held].pop());
  else if(q.it.cat==='prog') gradeProgChord(q);
}
function gradeInterval(q){ if(SES.answered) return; const ms=heldMidis().sort((a,b)=>a-b); if(ms.length<2) return;
  if(ms.length>2){ neutral(t('just_two')); return; }
  const lo=ms[0],hi=ms[1]; if(pc(lo)===q.key && hi-lo===q.it.semi){ [lo,hi].forEach(m=>kbState(m,'good',true)); resolve(q,true); } else { [lo,hi].forEach(m=>kbState(m,'bad',true)); setTimeout(()=>kbClear('bad'),500); q.missed=true; resolve(q,false); } }
function gradeChord(q){ if(SES.answered) return; const hp=heldPcs(), tpl=q.it.ref, target=chordTargetPcs(q.key,tpl); if(!hp.length) return;
  if(setEq(hp,target)){ const inv=inversionOf(q.key,tpl,Math.min(...heldMidis())); if(!data.settings.allowInv && inv!==0){ neutral(t('root_pos',rootName(q.key))); return; } heldMidis().forEach(m=>kbState(m,'good',true)); resolve(q,true); return; }
  if(isSubset(hp,target)){ neutral(t('keep_building')+' ('+hp.length+'/'+target.length+')'); return; }
  if(isSubset(target,hp)){ neutral(t('release_extra')); return; }
  if(hp.length>=target.length){ heldMidis().forEach(m=>kbState(m,'bad',true)); setTimeout(()=>kbClear('bad'),500); q.missed=true; resolve(q,false); } }
function gradeScaleNote(q,midi){ if(SES.answered||midi==null) return;
  if(q.idx===0){ if(pc(midi)!==q.key){ kbState(midi,'bad',true); setTimeout(()=>kbClear('bad'),400); neutral(t('start_on',rootName(q.key))); return; } q.anchor=midi; }
  const want=q.anchor+q.offs[q.idx];
  if(midi===want){ kbState(midi,'good',true); q.idx++; if(q.idx>=q.offs.length){ resolve(q,true); } else neutral(q.idx+' / '+q.offs.length+' ✓'); }
  else { kbState(midi,'bad',true); setTimeout(()=>kbClear('bad'),420); q.missed=true; resolve(q,false); } }
function gradeProgChord(q){ if(SES.answered) return; const ch=q.it.ref.chords[q.idx], root=(q.key+ch[0])%12, tpl=progChordTpl(ch[1]); const target=chordTargetPcs(root,tpl), hp=heldPcs(); if(!hp.length) return;
  if(setEq(hp,target)){ q.idx++; if(q.idx>=q.it.ref.chords.length){ resolve(q,true); } else { kbClear('target'); neutral('✓ — next chord'); setTimeout(()=>showProgTarget(q),250); } return; }
  if(isSubset(hp,target)||isSubset(target,hp)) return;
  if(hp.length>=target.length){ heldMidis().forEach(m=>kbState(m,'bad',true)); setTimeout(()=>kbClear('bad'),420); q.missed=true; resolve(q,false); } }
function neutral(msg){ const v=$('q-verdict'); v.className='verdict neutral'; v.textContent=msg; }

function resolve(q,correct){
  if(SES.answered) return; SES.answered=true; stopMetro(); stopDrone();
  const good = correct && !q.missed;
  if(SES.placement) seedPlacement(q.it.id, good); else if(!SES.targeted) reviewItem(q.it.id, good);   // targeted drills are free practice: no schedule, daily-goal or streak change
  SES.total++; if(good) SES.correct++;
  const v=$('q-verdict');
  if(correct && !q.missed){ v.className='verdict good'; v.textContent=randItem([t('correct1'),t('correct2'),t('correct3'),t('correct4')]); }
  else if(correct && q.ek){ v.className='verdict neutral'; v.textContent=t('ek_retry_ok',q.ek.tries+1); }   // reproduced after a miss: counts as a lapse
  else { v.className='verdict bad'; v.textContent=t('notquite'); }
  if(q.ek){ ekStop(q); $('q-ekreset').hidden=true; }
  revealAnswerKeys(q);
  showElaboration(q);
  if(!good){ setTimeout(()=>{ if(SES.active&&SES.q===q&&SES.answered) playQuestionSound(q); },600); }   // let the right answer be heard, not just seen
  $('q-reveal').hidden=true; $('q-next').hidden=false; $('q-next').focus();
}
function revealAnswerKeys(q){ const it=q.it;
  if(q.ek){ if(!q.ek.won){ kbClear('target'); kbClear('good'); q.ek.target.forEach(m=>kbState(m,'target',true)); } return; }
  if(it.cat==='interval'){ const r=60+q.key; [r,r+it.semi].forEach(m=>kbState(m,'target',true)); }
  else if(it.cat==='chord'){ const r=60+q.key; it.ref.intervals.forEach(i=>kbState(r+i,'target',true)); }
  else if(it.cat==='scale'){ const r=60+q.key; SCALES[it.name].concat([12]).forEach(o=>kbState(r+o,'target',true)); }
}
function showElaboration(q){ const it=q.it, e=$('q-elab'); let html='';
  if(it.cat==='interval'){ const s=songsFor(it.semi,'asc'); html='<b>'+ivName(it.semi)+'</b> = '+it.semi+' '+t('el_semitones')+(s.length&&!/^\(/.test(s[0])?' · '+t('el_soundslike')+' “'+s[0]+'”':''); }
  else if(it.cat==='chord'){ const f=feelDisp(it.short); html='<b>'+rootName(q.key)+dispSym(it.short)+'</b> = '+chordFormula(it.ref)+(f?' · '+f:''); }
  else if(it.cat==='scale'){ html='<b>'+scaleDisp(it.name)+'</b> · '+t('el_degrees')+' '+scaleFormula(SCALES[it.name]); }
  else if(it.cat==='prog'){ const chain=it.ref.chords.map(ch=>rootName((q.key+ch[0])%12)+dispSym(ch[1])).join(' · '), rom=it.ref.chords.map(ch=>ch[2]).join(' · '); html='<b>'+rom+'</b> — '+chain; }
  if(q.ek) html+='<br>'+ekElab(q);
  e.innerHTML=html; e.classList.add('show');
}

/* ============================================================================
   VIEWS / ROUTER
   ============================================================================ */
let _view='today';
function view0(){ return _view; }
const NAV_GROUPS={today:['today'],learn:['learn','songs','method'],practice:['practice','read','sing','analysis'],explore:['explore','accompany','transcribe'],progress:['progress']};
function navGroup(v){ return Object.keys(NAV_GROUPS).find(g=>NAV_GROUPS[g].includes(v)); }
const _modalStack=[]; let _modalBackPending=false, _modalAfterBack=null;
function pushModalState(id){
  if(_modalBackPending){ _modalAfterBack=id; _modalStack.length=0; _modalStack.push(id); return; }
  // Opening an overlay from the mobile menu replaces that temporary menu entry.
  if(id!=='menu' && history.state && history.state.modal==='menu' && !$('mobileMenu').hidden){
    closeMobileMenu(false,true); _modalStack.length=0;
    try{ history.replaceState({modal:id},'',location.href); _modalStack.push(id); }catch(_){}
    return;
  }
  if(!_modalStack.includes(id)){
    _modalStack.push(id);
    try{ history.pushState({modal:id},'',location.href); }catch(_){}
  }
}
function popModalState(id){
  const idx=_modalStack.indexOf(id);
  if(idx!==-1){
    _modalStack.splice(idx,1);
    if(_modalBackPending && _modalAfterBack===id){ _modalAfterBack=null; return; }
    if(history.state&&history.state.modal===id){
      try{ _modalBackPending=true; history.back(); }catch(_){ _modalBackPending=false; }
    }
  }
}
function closeMobileMenu(returnFocus=false,fromPop=false){
  const menu=$('mobileMenu');
  if(!menu||menu.hidden) return false;
  menu.hidden=true;
  $('menuBtn').setAttribute('aria-expanded','false');
  if(!fromPop) popModalState('menu');
  if(returnFocus) $('menuBtn').focus();
  return true;
}
function openMobileMenu(fromPop=false){
  const mm=$('mobileMenu');
  if(!fromPop) pushModalState('menu');
  mm.innerHTML='';
  document.querySelectorAll('#nav button').forEach(b=>{ const x=document.createElement('button'); x.textContent=b.textContent; x.dataset.view=b.dataset.view; x.setAttribute('aria-current',b.getAttribute('aria-current')||'false'); x.addEventListener('click',()=>show(x.dataset.view)); mm.appendChild(x); });
  mm.hidden=false; $('menuBtn').setAttribute('aria-expanded','true');
  (mm.querySelector('[aria-current="page"]')||mm.querySelector('button')).focus();
}
function renderModeNav(){
  const group=navGroup(view0()), views=NAV_GROUPS[group]||[];
  $('modeBar').hidden=views.length<2;
  $('modeNav').innerHTML=views.map(v=>`<button type="button" data-view="${v}" aria-current="${v===view0()?'page':'false'}">${t(v==='practice'?'nav_drills':'nav_'+v)}</button>`).join('');
}
function focusView(v){
  const view=$('view-'+v);
  const target=[...view.querySelectorAll('h1,h2')].find(el=>el.getClientRects().length)||view;
  target.tabIndex=-1;
  target.focus({preventScroll:true});
}
function show(v,moveFocus=true){
  if(!navGroup(v)) return;
  const prev=_view;
  if(location.hash.slice(1)!==v){ const viaModal=_modalStack.length>0; _modalStack.length=0;   // the modal's history entry becomes the new view's entry
    try{ history[(_routed&&!viaModal)?'pushState':'replaceState'](null,'','#'+v); }catch(_){} }
  _routed=true;
  if(v!=='today'){ data.lastTool=v; const tv=data.toolDay||(data.toolDay={}); tv[v]=todayN(); saveSoon(); }
  if(prev==='analysis'&&v!==prev){ scoreStop(); anKeysClear(); anSheet(false,true); }
  if(prev!==v){ releaseLiveInput(); stopPreviews(); kbClear('target'); kbDegrees(null); }
  _view=v;
  if(prev==='accompany' && v!=='accompany') accompStop();
  if(prev==='transcribe' && v!=='transcribe') trxStop();
  if(prev==='sing' && v!=='sing') singStopAll();
  if(prev==='read' && v!=='read'){ srStopAll(); rdAbort(); }
  document.querySelectorAll('.view').forEach(s=>s.classList.toggle('active', s.id==='view-'+v));
  document.querySelectorAll('#nav button').forEach(b=>b.setAttribute('aria-current', b.dataset.view===navGroup(v)?'page':'false'));
  dockSync();
  if(dockShown()) reflowKeys();   // reposition once the dock is laid out
  closeMobileMenu();
  if(SES.active && v!==sesHome()){ /* leaving mid-session */ endSession(false); }
  if(v==='today' && !SES.active){ $('today-home').style.display='block'; $('summary').style.display='none'; refreshToday(); }
  if(v==='explore'){ updateExplore(); cofPaintDock(); }
  if(v==='analysis') anDraw();
  if(v==='learn') renderLearn();
  if(v==='read') renderRead();
  if(v==='songs') renderSongs();
  if(v==='progress') renderProgress();
  if(v==='accompany') renderAccompany();
  if(v==='transcribe') renderTranscribe();
  if(v==='sing') renderSing();
  if(v==='practice' && !SES.active){ stopMetro(); renderPracticeLast(); }
  renderModeNav();
  syncIdle();   // a language/notation/label choice another tab made while this one was busy
  const active=document.activeElement;
  if(moveFocus&&(!active||active===document.body||!active.isConnected||!active.getClientRects().length)) focusView(v);
}
let _routed=false;
window.addEventListener('popstate',e=>{
  // The destination history entry, not the previously visible overlay, determines the UI.
  if(_modalBackPending){
    _modalBackPending=false;
    const next=_modalAfterBack; _modalAfterBack=null;
    if(next){ _modalStack.length=0; try{ history.pushState({modal:next},'',location.href); _modalStack.push(next); }catch(_){} return; }
  }
  const modal=e.state&&e.state.modal;
  _modalStack.length=0;
  if(modal==='menu'||modal==='help'||modal==='drawer') _modalStack.push(modal);
  if(modal!=='menu'){
    const menu=$('mobileMenu'), returnFocus=!modal && menu.contains(document.activeElement) && location.hash.slice(1)===_view;
    closeMobileMenu(returnFocus,true);
  }
  if(modal!=='help' && $('helpBox').classList.contains('on')) openHelp(false,true);
  if(modal!=='drawer' && $('drawer').classList.contains('on')) openDrawer(false,true);
  const v=location.hash.slice(1);
  if(navGroup(v) && v!==_view){ _routed=false; show(v); }
  if(modal==='menu' && getComputedStyle($('menuBtn')).display!=='none' && $('mobileMenu').hidden) openMobileMenu(true);
  if(modal==='help' && !$('helpBox').classList.contains('on')) openHelp(true,true);
  if(modal==='drawer' && !$('drawer').classList.contains('on')) openDrawer(true,true);
});

/* ---------- TODAY ---------- */
function greeting(){ const h=new Date().getHours(); return h<5?t('g_late'):h<12?t('g_morning'):h<18?t('g_afternoon'):t('g_evening'); }
function refreshToday(){
  const gr=greeting(); $('greet-title').textContent=/[.?!…]$/.test(gr)?gr:gr+'.';
  const tn=todayN();
  $('streakN').textContent=currentStreak();
  const goal=data.settings.goal, done=Math.min(data.todayDay===tn?data.todayCount:0,goal);
  const gd=$('goaldots'); gd.innerHTML=''; const dots=5; for(let i=0;i<dots;i++){ const x=document.createElement('i'); if(i < Math.round(dots*done/goal)) x.className='on'; gd.appendChild(x); }
  gd.setAttribute('aria-label',t('goal_aria',done,goal)); $('goal-txt').textContent=t('goal_txt',done,goal);
  const due=dueItems().length, fresh=Math.min(newItemsAvail().length, newQuotaLeft());
  $('c-due').textContent=due; $('c-new').textContent=fresh; $('c-mastered').textContent=masteredCount();
  $('placeBtn').hidden = !(!data.placed && (data.totalReviews||0)===0);   // offer placement only to brand-new users
  const next=dueItems()[0]||(fresh?newItemsAvail()[0]:null);
  $('nextup').innerHTML = next ? (t('nextup')+' <b>'+itemLabel(next)+'</b> · '+catLabel(next.cat).toLowerCase()) : t('nextup_none');
  const caughtUp = due===0 && fresh===0;
  $('startBtn').textContent = caughtUp ? t('start_caught') : t('start');
  $('hero-title').textContent = caughtUp ? t('hero_caught') : t('hero_session');
  $('why-text').textContent = caughtUp ? t('why_caught') : t('why_due');
  // focus grid
  const fg=$('focusGrid'); fg.innerHTML='';
  Object.keys(CATS).forEach(cat=>{ const items=ITEMS.filter(it=>it.cat===cat); const mastered=items.filter(it=>boxOf(it.id)>=4).length; const seen=items.filter(it=>!isNew(it.id)).length;
    const card=document.createElement('button'); card.type='button'; card.className='focus'; card.onclick=()=>{ show('practice'); $('pr-cat').value=cat; $('pr-cat').dispatchEvent(new Event('change')); $('pr-start').focus(); };
    card.innerHTML='<div class="k">'+catLabel(cat)+'</div><div class="m">'+mastered+' '+t('mastered_lc')+' · '+seen+'/'+items.length+' '+t('started')+'</div><div class="bar"><i style="width:'+Math.round(100*mastered/items.length)+'%"></i></div>';
    fg.appendChild(card); });
  renderPlan();
}

/* ---------- EXPLORE ---------- */
let explorePreview=[], exploreTimers=[];
function clearExplorePreview(){ exploreTimers.forEach(clearTimeout); exploreTimers=[]; explorePreview=[]; if(view0()==='explore') updateExplore(); }
function exploreSequence(events){
  if(view0()!=='explore') return;
  clearExplorePreview();
  if(reduceMotion()&&events.length>2){ const last=events[events.length-1];   // reduced motion: one steady picture of every note instead of a light running across the keys
    events=[{at:0,notes:[...new Set(events.flatMap(e=>e.notes))].sort((a,b)=>a-b)}].concat(last.notes.length?[]:[last]); }
  events.forEach(e=>{
    const paint=()=>{ explorePreview=e.notes; updateExplore(); };
    if(e.at===0) paint(); else exploreTimers.push(setTimeout(paint,e.at));
  });
}
// Bass on the left and treble on the right, as on the keyboard. The frame never changes, so nothing moves while you play: each clef shows
// the exact sounding octave up to EX_LEDGERS ledger lines, and lists any note further away beside an arrow at its edge.
const EX_LEDGERS=5;
function drawExploreStaff(midis,flat){
  const wrap=$('ex-staff'); if(!wrap) return;
  const names=flat?['C','Db','D','Eb','E','F','Gb','G','Ab','A','Bb','B']:['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'];
  const pitches=[...new Set(midis)].map(m=>{
    const name=names[pc(m)], li='CDEFGAB'.indexOf(name[0]), oct=Math.floor(m/12)-1;
    return {m,step:ssStepOf(li,oct),acc:name.slice(1)};
  }).sort((a,b)=>a.step-b.step||a.m-b.m);
  const W=520, H=234, top=94, room=EX_LEDGERS*12+6;
  let body='';
  [['bass',16,250],['treble',270,504]].forEach(([clef,x0,x1])=>{
    const treble=clef==='treble', ref=treble?30:18, x=x0+146, far={up:[],down:[]};
    body+=`<g class="ex-stave" data-clef="${clef}"><text class="ss-syl" x="${x0+24}" y="${top-24}">${t(treble?'si_treble':'si_bass')}</text>`;
    for(let i=0;i<5;i++) body+=`<line class="ss-line" x1="${x0}" y1="${top+i*12}" x2="${x1}" y2="${top+i*12}" stroke-width="1.2"/>`;
    body+=srClef(clef,x0+16,top);
    // Adjacent pitches use alternating head columns; accidentals have collision-free lanes.
    let prevStep=-Infinity, prevLane=0; const accLanes=[], heads=[];
    pitches.forEach(p=>{
      const y=top+48+(ref-p.step)*6;
      if(y<top-room||y>top+48+room){ far[y<top?'up':'down'].push(noteName(p.m,flat)); return; }
      const lane=p.step-prevStep<=1?1-prevLane:0;
      prevStep=p.step; prevLane=lane; heads.push({p,y,lane});
    });
    // One set of ledger lines per chord, wide enough for whichever head columns need them.
    const ledgers=new Map();
    heads.forEach(({y,lane})=>{
      for(let ly=top-12; ly>=y-1; ly-=12) ledgers.set(ly,Math.max(ledgers.get(ly)||0,lane));
      for(let ly=top+60; ly<=y+1; ly+=12) ledgers.set(ly,Math.max(ledgers.get(ly)||0,lane));
    });
    ledgers.forEach((lane,ly)=>{ body+=`<line class="ss-ledger" x1="${x-9}" y1="${ly}" x2="${x+9+lane*13}" y2="${ly}" stroke="#1a1714" stroke-width="1.2"/>`; });
    heads.forEach(({p,y,lane})=>{
      let accidental='';
      if(p.acc){
        let a=accLanes.findIndex(last=>Math.abs(last-y)>=24); if(a<0) a=accLanes.length;
        accLanes[a]=y; accidental=p.acc==='#'?ssSharp(x-20-a*11,y):ssFlat(x-20-a*11,y);
      }
      body+=`<g class="ss-n" data-midi="${p.m}" data-clef="${clef}"><title>${noteName(p.m,flat)}</title>${accidental}${ssNotehead(x+lane*13,y,4)}</g>`;
    });
    // Listed far notes shrink rather than spill into the other staff; 7px a character overestimates 11px text.
    [['up','↑',14],['down','↓',H-6]].forEach(([k,arrow,y])=>{
      if(!far[k].length) return;
      const s=`${arrow} ${far[k].join(' ')}`, max=x1-x0-16, est=s.length*7, w=Math.min(est,max), cx=Math.min(Math.max(x,x0+8+w/2),x1-8-w/2);
      body+=`<text class="ss-syl ex-far" x="${cx}" y="${y}"${est>max?` style="font-size:${(11*max/est).toFixed(1)}px"`:''}>${s}</text>`;
    });
    body+='</g>';
  });
  if(!pitches.length) body+=`<text class="ss-syl" x="${W/2}" y="${top+88}">${t('ex_staff_empty')}</text>`;
  const label=t('ex_staff_label')+(midis.length?': '+midis.map(m=>noteName(m,flat)).join(', '):'');
  wrap.setAttribute('aria-label',label);
  wrap.innerHTML=`<svg class="ss-svg" role="img" aria-label="${label}" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" style="width:100%; height:auto; max-width:700px; margin:auto" xmlns="http://www.w3.org/2000/svg">${body}</svg>`;
}

function fillRoots(sel,withAll){ sel.innerHTML=''; if(withAll){ const o=document.createElement('option'); o.value='all'; o.textContent=t('all_keys'); sel.appendChild(o); } NOTE_SYS[notation].root.forEach((n,i)=>{ const o=document.createElement('option'); o.value=i; o.textContent=n; sel.appendChild(o); }); }
function fillKeyCtx(){ const sel=$('keyCtx'); sel.innerHTML='<option value="-1">'+t('none_ctx')+'</option>'; NOTE_SYS[notation].root.forEach((n,i)=>{ const o=document.createElement('option'); o.value=i; o.textContent=t('key_major',n); sel.appendChild(o); }); }
function fillRefNames(){ const rt=$('refType').value, sel=$('refName'); sel.innerHTML='';
  if(rt==='chord'){ CHORDS.forEach(c=>{ const o=document.createElement('option'); o.value=c.symbol; o.textContent=c.symbol; sel.appendChild(o); }); }
  else { Object.keys(SCALES).forEach(n=>{ const o=document.createElement('option'); o.value=n; o.textContent=scaleDisp(n); sel.appendChild(o); }); } }
function refMidis(){ const root=60+parseInt($('refRoot').value,10); if($('refType').value==='chord'){ const c=CHORDS.find(x=>x.symbol===$('refName').value); return c.intervals.map(i=>root+i); } return SCALES[$('refName').value].concat([12]).map(i=>root+i); }
function updateExplore(){ if(view0()!=='explore') return; const notes=(held.size?heldMidis():explorePreview).slice().sort((a,b)=>a-b); const keyCtx=parseInt($('keyCtx').value,10); let nameLabel='—',roman='—',spell=notes.length?isFlatKey(pc(notes[0])):false;
  let degrees=null;
  if(notes.length>=3){ const id=identifyChord(notes); if(id) spell=isFlatKey(id.rootPc); if(id){ nameLabel=slashLabel(id)+(id.inversion>0?' · '+invName(id.inversion):''); roman=romanFor(keyCtx,id)||'—'; degrees=chordDegreeMap(notes,id.rootPc,id.chord.pcset); } else nameLabel='—'; }
  else if(notes.length===2){ nameLabel=intervalLabel(notes[1]-notes[0]); }
  else if(notes.length===1){ nameLabel=pcName(pc(notes[0]),spell); }
  kbDegrees(degrees);
  $('ro-notes').textContent=notes.length?notes.map(m=>noteName(m,spell)).join('  '):'—'; $('ro-name').textContent=nameLabel; $('ro-roman').textContent=roman; drawExploreStaff(notes,spell); cofNow(notes); }
