// Keeps the circle in step with the "Key context" select from the Free-play tab (always a major key there).
function circleSel(){ const k=parseInt($('keyCtx').value,10); if(k>=0){ cof.i=CIRCLE.indexOf(k); cof.minor=false; cof.picked=true; } cofSel(); cofInfo(); cofPaintDock(); }
function cofPick(i,minor){ cof.i=i; cof.minor=minor; cof.picked=true;
  $('keyCtx').value=CIRCLE[i]; cofSyncRef(); cofSel(); cofInfo(); cofPaintDock(); cofRevealFingering(); cofPlay(); }
function cofRevealFingering(){ requestAnimationFrame(()=>{
  const fing=document.querySelector('#exp-circle .cof-fing'); if(!fing||$('exp-circle').hidden) return;
  const dock=document.body.classList.contains('kb')?$('dock'):null, dockH=dock?dock.getBoundingClientRect().height:0;
  const header=document.querySelector('header'), top=(header?header.getBoundingClientRect().bottom:0)+16, bottom=window.innerHeight-dockH-24;
  const rect=fing.getBoundingClientRect(), available=Math.max(0,bottom-top);
  const delta=rect.height>available||rect.top<top?rect.top-top:rect.bottom>bottom?rect.bottom-bottom:0;
  if(Math.abs(delta)>1) window.scrollBy({top:delta,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});
}); }
function cofSyncRef(){ $('refType').value=cof.mode; fillRefNames(); $('refRoot').value=cofTonicPc();
  $('refName').value=cof.mode==='chord'?(cof.minor?'m':'maj'):(cof.minor?COF_SCALE[cof.flavor]:'Major (Ionian)'); }
