const GLOSS=[
{l:'keys',en:['Semitone (half step)','The smallest distance on the piano: one key to the very next, black or white.'],ro:['Semiton','Cea mai mică distanță la pian: de la o clapă la imediat următoarea, albă sau neagră.']},
{l:'keys',en:['Whole tone (whole step)','Two semitones, e.g. C–D.'],ro:['Ton','Două semitonuri, de ex. Do–Re.']},
{l:'keys',en:['Octave','Same letter name 12 semitones higher or lower; frequency doubles.'],ro:['Octavă','Aceeași notă cu 12 semitonuri mai sus sau mai jos; frecvența se dublează.']},
{l:'keys',en:['Enharmonic','Two names for the same key, e.g. F♯ = G♭.'],ro:['Enarmonic','Două nume pentru aceeași clapă, de ex. Fa♯ = Sol♭.']},
{l:'notation',en:['Grand staff','Treble and bass staves joined by a brace; middle C sits between them.'],ro:['Portativ dublu','Portativele în cheia Sol și Fa unite cu acoladă; Do central e între ele.']},
{l:'notation',en:['Clef','Sign that fixes which line is which note (treble = G, bass = F).'],ro:['Cheie','Semnul care fixează ce notă e pe o linie (cheia Sol, cheia Fa).']},
{l:'notation',en:['Ledger line','Short extra line for notes above or below the staff.'],ro:['Linie suplimentară','Linie scurtă pentru notele de deasupra sau de sub portativ.']},
{l:'notation',en:['Accidental','♯, ♭ or ♮ placed before a note; lasts until the barline.'],ro:['Alterație','♯, ♭ sau ♮ pus înaintea notei; ține până la bara de măsură.']},
{l:'cof',en:['Key signature','Sharps or flats at the start of each line that apply all piece long.'],ro:['Armură','Diezii sau bemolii de la începutul fiecărui rând, valabili toată piesa.']},
{l:'rh',en:['Time signature','Top number = beats per bar; bottom = which note gets the beat.'],ro:['Măsură (indicație)','Cifra de sus = timpi pe măsură; cea de jos = ce valoare primește un timp.']},
{l:'rh',en:['Dotted note','A dot adds half the note\'s value: dotted half = 3 beats.'],ro:['Notă cu punct','Punctul adaugă jumătate din valoare: doimea cu punct = 3 timpi.']},
{l:'rh2',en:['Tie','Curved line joining two equal pitches: hold, don\'t replay.'],ro:['Legato de prelungire','Arc între două note identice: le ții, nu o repeți.']},
{l:'rh2',en:['Triplet','Three notes in the time of two, marked with a 3.'],ro:['Triolet','Trei note în timpul a două, marcate cu 3.']},
{l:'rh2',en:['Syncopation','Accent on a weak beat or off-beat.'],ro:['Sincopă','Accent pe un timp slab sau între timpi.']},
{l:'rh2',en:['Compound metre','Beats divide in three (6/8, 9/8, 12/8).'],ro:['Măsură compusă','Timpii se împart în trei (6/8, 9/8, 12/8).']},
{l:'rh2',en:['Tempo','Speed of the beat, in BPM or Italian terms (Adagio, Allegro…).'],ro:['Tempo','Viteza pulsului, în BPM sau termeni italieni (Adagio, Allegro…).']},
{l:'dyn',en:['Dynamics','Loudness marks: pp, p, mp, mf, f, ff.'],ro:['Nuanțe','Semne de intensitate: pp, p, mp, mf, f, ff.']},
{l:'dyn',en:['Crescendo / diminuendo','Gradually louder / gradually softer (hairpins).'],ro:['Crescendo / diminuendo','Treptat mai tare / treptat mai încet („furculițe”).']},
{l:'dyn',en:['Staccato','Dot above/below: short, detached.'],ro:['Staccato','Punct deasupra/dedesubt: scurt, detașat.']},
{l:'dyn',en:['Legato','Smooth and connected, shown by a slur.'],ro:['Legato','Legat și cursiv, arătat printr-un arc.']},
{l:'symbols',en:['Repeat sign','Double bar with dots: play the section again.'],ro:['Semn de repetiție','Bară dublă cu puncte: repeți secțiunea.']},
{l:'symbols',en:['D.C. al Fine','Go back to the beginning and stop at Fine.'],ro:['D.C. al Fine','Te întorci la început și te oprești la Fine.']},
{l:'symbols',en:['D.S. al Coda','Go back to the sign 𝄋, then jump to the coda 𝄌 when told.'],ro:['D.S. al Coda','Te întorci la semnul 𝄋, apoi sari la coda 𝄌 când scrie.']},
{l:'symbols',en:['Fermata','𝄐 Hold the note longer than written.'],ro:['Coroană (fermata)','𝄐 Ții nota mai mult decât e scris.']},
{l:'symbols',en:['Sustain pedal','Ped. … ✱: right pedal down, then up.'],ro:['Pedală de rezonanță','Ped. … ✱: apeși pedala dreaptă, apoi o ridici.']},
{l:'symbols',en:['Ornament','Decoration such as trill (tr), mordent or grace note.'],ro:['Ornament','Înfrumusețare: tril (tr), mordent, apogiatură.']},
{l:'iv',en:['Interval','Distance between two notes, counted in letter steps and semitones.'],ro:['Interval','Distanța dintre două note, numărată în trepte și semitonuri.']},
{l:'iv',en:['Perfect fifth','7 semitones (C–G); the most stable interval after the octave.'],ro:['Cvintă perfectă','7 semitonuri (Do–Sol); cel mai stabil interval după octavă.']},
{l:'iv2',en:['Tritone','6 semitones: augmented 4th / diminished 5th (C–F♯).'],ro:['Tritonus','6 semitonuri: cvartă mărită / cvintă micșorată (Do–Fa♯).']},
{l:'iv2',en:['Inversion (interval)','Flip the lower note up an octave; numbers add to 9, major↔minor.'],ro:['Răsturnarea intervalului','Muți nota de jos cu o octavă sus; cifrele dau 9, mare↔mică.']},
{l:'iv2',en:['Compound interval','Larger than an octave: 9th = 2nd + octave.'],ro:['Interval compus','Mai mare de o octavă: nona = secunda + octavă.']},
{l:'sc',en:['Major scale','Steps W W H W W W H.'],ro:['Gama majoră','Pași T T S T T T S.']},
{l:'sc',en:['Scale degree','Position in the scale: tonic, supertonic, mediant, subdominant, dominant, submediant, leading tone.'],ro:['Treaptă','Locul în gamă: tonică, supertonică, medianta, subdominantă, dominantă, submedianta, sensibilă.']},
{l:'minor',en:['Relative minor','Minor key sharing a key signature, a minor 3rd below (C → A minor).'],ro:['Relativa minoră','Tonalitatea minoră cu aceeași armură, o terță mică mai jos (Do → la minor).']},
{l:'minor',en:['Harmonic minor','Natural minor with a raised 7th (leading tone).'],ro:['Minor armonic','Minorul natural cu treapta a 7-a urcată (sensibilă).']},
{l:'minor',en:['Melodic minor','Raised 6th and 7th going up; natural minor coming down (classical).'],ro:['Minor melodic','Treptele 6 și 7 urcate la urcare; minor natural la coborâre (clasic).']},
{l:'cof',en:['Circle of fifths','Keys arranged by perfect fifths; each step adds one sharp or flat.'],ro:['Cercul cvintelor','Tonalitățile așezate din cvintă în cvintă; fiecare pas adaugă un diez sau un bemol.']},
{l:'modes',en:['Mode','Scale built by starting the major pattern on another degree (Dorian, Lydian…).'],ro:['Mod','Gamă obținută pornind tiparul majorului de pe altă treaptă (doric, lidic…).']},
{l:'ch',en:['Triad','Three-note chord stacked in thirds: root, 3rd, 5th.'],ro:['Trison','Acord de trei note suprapuse în terțe: fundamentală, terță, cvintă.']},
{l:'ch',en:['Chord inversion','A chord with a note other than the root in the bass.'],ro:['Răsturnarea acordului','Acord cu altă notă decât fundamentala în bas.']},
{l:'ch7',en:['Seventh chord','Triad plus a 7th: maj7, 7, m7, m7♭5, dim7.'],ro:['Acord de septimă','Trison plus septimă: maj7, 7, m7, m7♭5, dim7.']},
{l:'ch7',en:['Slash chord','Chord/bass note, e.g. C/E = C chord with E in the bass.'],ro:['Acord cu bas (slash)','Acord/notă în bas, de ex. Do/Mi = Do major cu Mi în bas.']},
{l:'ch7',en:['Suspended chord','The 3rd is replaced by a 2nd (sus2) or 4th (sus4).'],ro:['Acord suspendat','Terța e înlocuită cu secunda (sus2) sau cvarta (sus4).']},
{l:'pr',en:['Roman numerals','Chords named by scale degree: I, ii, iii, IV, V, vi, vii°.'],ro:['Cifre romane','Acorduri numite după treaptă: I, ii, iii, IV, V, vi, vii°.']},
{l:'pr',en:['12-bar blues','I-I-I-I / IV-IV-I-I / V-IV-I-V, usually with 7th chords.'],ro:['Blues pe 12 măsuri','I-I-I-I / IV-IV-I-I / V-IV-I-V, de obicei cu acorduri de septimă.']},
{l:'cad',en:['Cadence','Chord pair that ends a phrase: authentic, plagal, half, deceptive.'],ro:['Cadență','Pereche de acorduri care încheie o frază: autentică, plagală, semicadență, întreruptă.']},
{l:'cad',en:['Voice leading','Moving each voice smoothly, by step or common tone.'],ro:['Conducerea vocilor','Fiecare voce se mișcă lin, pe treaptă sau prin notă comună.']},
{l:'nct',en:['Non-chord tone','Melody note outside the chord: passing, neighbour, suspension, appoggiatura.'],ro:['Notă străină','Notă din melodie din afara acordului: de trecere, broderie, întârziere, apogiatură.']},
{l:'secdom',en:['Secondary dominant','V of a chord other than I, e.g. V/V (D7 in C).'],ro:['Dominantă secundară','V al altui acord decât I, de ex. V/V (Re7 în Do).']},
{l:'secdom',en:['Modulation','Moving to a new key and establishing it with a cadence.'],ro:['Modulație','Trecerea într-o tonalitate nouă, confirmată printr-o cadență.']},
{l:'form',en:['Motif','Short musical idea that is repeated and varied.'],ro:['Motiv','Idee muzicală scurtă, repetată și variată.']},
{l:'form',en:['Phrase / period','Phrase = musical sentence ending in a cadence; period = question + answer phrases.'],ro:['Frază / perioadă','Fraza = propoziție muzicală încheiată cu o cadență; perioada = întrebare + răspuns.']},
{l:'form',en:['Binary / ternary / rondo','AB, ABA and ABACA forms.'],ro:['Formă bipartită / tripartită / rondo','Formele AB, ABA și ABACA.']},
{l:'accomp',en:['Alberti bass','Broken chord low–high–middle–high.'],ro:['Bas Alberti','Acord desfăcut jos–sus–mijloc–sus.']},
{l:'accomp',en:['Lead sheet','Melody plus chord symbols; you improvise the accompaniment.'],ro:['Lead sheet','Melodie plus simboluri de acorduri; acompaniamentul îl improvizezi.']}];
function lgNorm(s){ return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(); }
function lgHTML(){ const k=(GLOSS[0]&&GLOSS[0][lang])?lang:'en', list=GLOSS.slice().sort((a,b)=>((a[k]?a[k][0]:a.en[0])).localeCompare(b[k]?b[k][0]:b.en[0],lang));
  return '<h3 tabindex="-1">📖 '+t('lg_title')+'</h3><label class="lg-search"><span>'+t('lg_search')+'</span><input type="search" id="lg-q" placeholder="'+t('lg_ph')+'" autocomplete="off"></label>'+ 
    '<p class="lg-n" id="lg-n" aria-live="polite"></p><dl class="lg-list">'+list.map(g=>{ const L=LESSONS.find(x=>x.id===g.l); const cur=g[k]||g.en;
      return '<div class="lg-it" data-k="'+lgNorm(cur[0]+' '+cur[1]+' '+g.en[0]).replace(/"/g,'')+'"><dt>'+cur[0]+'</dt><dd>'+cur[1]+(L?' <a href="#" data-lgo="'+L.id+'">'+L.icon+' '+learnTitle(L)+'</a>':'')+'</dd></div>'; }).join('')+'</dl>'+ 
    '<div class="learn-nav"><button type="button" class="btn ghost sm" data-lgback="1">'+t('lg_close')+'</button></div>'; }
function lgFilter(){ const q=$('lg-q'), v=q?lgNorm(q.value.trim()):''; let n=0;
  document.querySelectorAll('#learnBody .lg-it').forEach(it=>{ const on=!v||it.dataset.k.includes(v); it.hidden=!on; if(on) n++; });
  const o=$('lg-n'); if(o) o.textContent=n?t('lg_n',n):t('lg_none',q.value.trim()); }

(function initTheoryI18n(){
  if (typeof I18N_PAYLOADS === 'undefined') return;
  for (const [lKey, p] of Object.entries(I18N_PAYLOADS)) {
    if (p.lessons) {
      LESSONS.forEach(L => { if (p.lessons[L.id]) L[lKey] = p.lessons[L.id]; });
    }
    if (p.units) {
      LEARN_UNITS.forEach(u => { if (p.units[u.id]) u[lKey] = p.units[u.id]; });
    }
    if (p.glossary) {
      GLOSS.forEach((g, i) => { const item = p.glossary[String(i)]; if (item) g[lKey] = [item.term, item.definition]; });
    }
    if (p.quizzes) {
      Object.entries(p.quizzes).forEach(([lid, qs]) => {
        const targetList = LQZ[lid];
        if (targetList) {
          targetList.forEach((q, qi) => {
            if (qs[qi]) {
              q.i18n = q.i18n || {
                en: { q: Array.isArray(q.q)?q.q[0]:q.q, why: Array.isArray(q.why)?q.why[0]:q.why, o: q.o?q.o.map(x=>Array.isArray(x)?x[0]:x):null },
                ro: { q: Array.isArray(q.q)?q.q[1]:q.q, why: Array.isArray(q.why)?q.why[1]:q.why, o: q.o?q.o.map(x=>Array.isArray(x)?x[1]:x):null }
              };
              q.i18n[lKey] = { q: qs[qi].q, why: qs[qi].why, o: qs[qi].o };
            }
          });
        }
      });
    }
    if (p.summaries) {
      Object.entries(p.summaries).forEach(([lid, rows]) => {
        const targetList = LSUM[lid];
        if (targetList) {
          targetList.forEach((r, ri) => {
            if (rows[ri]) {
              r.i18n = r.i18n || {
                en: [Array.isArray(r[0])?r[0][0]:r[0], Array.isArray(r[1])?r[1][0]:r[1]],
                ro: [Array.isArray(r[0])?r[0][1]:r[0], Array.isArray(r[1])?r[1][1]:r[1]]
              };
              r.i18n[lKey] = [rows[ri][0], rows[ri][1]];
            }
          });
        }
      });
    }
  }
})();

