/* ---- sessions: intro → questions → summary ---- */
function rdLvName(L){ return L.custom?t('rdx_custom'):t('rdx_u_'+L.u)+' · '+L.n; }
function rdRangeTxt(L){ if(L.set) return L.set.map(s=>rdName(rdP(s),true)).join(' · '); if(L.lo) return rdName(rdP(L.lo),true)+'–'+rdName(rdP(L.hi),true); return ''; }
