  if(RD.rh){ RD.rh.playing=false; cancelAnimationFrame(RD.rh.raf); if(RD.rh.open) RD.rh.open.clear(); if(RD.rh.two) rdRhMarks(false); } (RD.nodes||[]).forEach(n=>{ try{ n.stop(0); }catch(_){} }); RD.nodes=[];
