  if(acc<60) return {k:'rdn_rh_low'}; if(mean<-35) return {k:'rdn_rh_rush',args:()=>[Math.round(-mean)]}; if(mean>35) return {k:'rdn_rh_drag',args:()=>[Math.round(mean)]};
