 if(weak.length&&acc<95) return {k:'rdn_weak',args:()=>[weak.slice(0,3).map(([k])=>rdKeyText(k)).join(', ')],act:mode==='practice'?null:{k:'rdn_act_practice',run:()=>rdStart('practice')}};
 if(sec>tg) return {k:'rdn_speed',args:()=>[anNum(sec,1),anNum(tg,1)],act:{k:'rdn_act_rush',run:()=>rdStart('rush')}};
