 const k=sym.kind, v=sym.val;
 if(k==='rest'){ const name=t('sym_rest_'+v.type), raw=v.dots===1?t('sym_rest_dotted',name):v.dots>1?t('sym_rest_dots',name,v.dots):name, head=raw[0].toLocaleUpperCase(lang)+raw.slice(1);
  const body=t(v.type==='measure'?'sym_rest_measure_body':'sym_rest_body'); return {head,body,line:head+' — '+body}; }
 if(k==='text'){ const parts=scoreTermParts(v); return {head:v,body:parts.join(' · '),line:v+' · '+parts.join(' · ')}; }
 let full;
 if(k==='dyn') full=t('sym_dyn_'+(v==='sf'?'sfz':v==='sfp'?'fp':v));
 else if(k==='finger'){ const ds=(v.match(/[1-5]/g)||[]); full=ds.length>1?t('sym_finger_sub',ds.join(', '),ds.map(d=>d+' = '+t('sym_f'+d)).join(', ')):ds.length?t('sym_finger',ds[0],t('sym_f'+ds[0])):t('sym_finger','?','?'); }
 else if(k==='rehearsal') full=t('sym_rehearsal');
 else if(k==='key') full=t('sym_key',v);
 else if(k==='time'){ const [a,b]=v.split('/'); full=t('sym_time',a,b); }
