  if((x<b.left+b.width*0.08||x>b.right-b.width*0.3)&&now-SCORE.panAt>500){ SCORE.panAt=now; box.scrollTo({left:box.scrollLeft+(x-b.left)-b.width*0.15,behavior}); }
