function fallBurst(k,y,c){ const x=k.x+k.w/2; FALL.flashes.push({x,y,w:k.w,rgb:c.rgb,life:.3,max:.3});
 for(let i=0;i<8;i++){ const a=-Math.PI/2+(Math.random()-.5)*1.6, v=70+Math.random()*130; FALL.particles.push({x:x+(Math.random()-.5)*k.w*.6,y:y-2,vx:Math.cos(a)*v,vy:Math.sin(a)*v,r:.8+Math.random()*1.7,life:.35+Math.random()*.3,max:.65,col:c.lit[0]}); }
 if(FALL.particles.length>300) FALL.particles.splice(0,FALL.particles.length-300); }
function fallParticles(ctx,dt){
 ctx.save(); ctx.globalCompositeOperation='lighter';
 FALL.flashes=FALL.flashes.filter(f=>(f.life-=dt)>0);
 for(const f of FALL.flashes){ const a=f.life/f.max, rad=f.w*.8+22*(1-a), g=ctx.createRadialGradient(f.x,f.y,0,f.x,f.y,rad); g.addColorStop(0,'rgba('+f.rgb+','+(.7*a).toFixed(3)+')'); g.addColorStop(1,'rgba('+f.rgb+',0)'); ctx.fillStyle=g; ctx.fillRect(f.x-rad,f.y-rad,rad*2,rad); }
 FALL.particles=FALL.particles.filter(p=>(p.life-=dt)>0);
 for(const p of FALL.particles){ p.x+=p.vx*dt; p.y+=p.vy*dt; p.vy+=180*dt; ctx.globalAlpha=Math.min(1,p.life/p.max*1.5); ctx.fillStyle=p.col; ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,Math.PI*2); ctx.fill(); }
 ctx.restore();
}
// Realistic keys: white keys with a soft gradient and front lip, glossy black keys; pressed keys light up in the hand colour and dip.
// Keys you hold yourself show in gold; keys "Wait for me" is waiting for pulse.
function fallKeyboard(ctx,G,y,kh,W,active,P,need,ms){
 P=P||FALL_COL; const mineHeld=new Set(held.keys?held.keys():held), pulse=.55+.45*Math.sin((ms||0)/170), wait=new Set(need||[]);
 const tint=m=>{ const h=active.get(m); if(h) return P[h].key; if(mineHeld.has(m)) return FALL_YOU; return null; };
 ctx.fillStyle='#110e0c'; ctx.fillRect(0,y,W,kh);
 const r=Math.min(4,G.kw*.12), lab=labelMode!=='none', dark=document.documentElement.getAttribute('data-theme')==='dark';
 for(const m of G.whites){ const k=G.keys.get(m), c=tint(m), dip=c?3.5:0, x=k.x+.75, w=k.w-1.5, h=kh-1-dip, g=ctx.createLinearGradient(0,y+dip,0,y+dip+h);
  if(c){ if(c===FALL_YOU){ g.addColorStop(0,'#fff8e2'); g.addColorStop(.35,'#fde492'); g.addColorStop(.78,'#f4c450'); g.addColorStop(1,'#df9f20'); } else { g.addColorStop(0,c[0]); g.addColorStop(1,c[1]); } } else if(dark){ g.addColorStop(0,'#ece5d8'); g.addColorStop(.3,'#ded6c8'); g.addColorStop(.8,'#d2c7b5'); g.addColorStop(1,'#c4b7a2'); } else { g.addColorStop(0,'#ffffff'); g.addColorStop(.3,'#fdfcf9'); g.addColorStop(.8,'#f5eee1'); g.addColorStop(1,'#ebe0ce'); }
  ctx.fillStyle=g; fallKeyPath(ctx,x,y+dip,w,h,r); ctx.fill(); ctx.strokeStyle=c?(c===FALL_YOU?'#cca02d':'rgba(0,0,0,.25)'):(dark?'#2a2520':'#c2b8a7'); ctx.lineWidth=1; fallKeyPath(ctx,x,y+dip,w,h,r); ctx.stroke();
  if(wait.has(m)){ ctx.fillStyle='rgba(255,196,64,'+(.35+.4*pulse).toFixed(3)+')'; fallKeyPath(ctx,x,y+dip,w,h,r); ctx.fill(); }
  const lip=ctx.createLinearGradient(0,y+dip+h-7,0,y+dip+h); lip.addColorStop(0,'rgba(0,0,0,0)'); lip.addColorStop(1,dark?'rgba(85,75,65,.35)':'rgba(180,165,140,.35)'); ctx.fillStyle=lip; ctx.fillRect(x+1,y+dip+h-7,w-2,7);
  if(lab&&(pc(m)===0||labelMode==='all')&&k.w>=14){ const nm=noteName(m,false); ctx.font='600 '+Math.round(Math.min(11,Math.max(8,k.w*.3)))+'px '+FALL_FONT; ctx.textAlign='center'; ctx.textBaseline='alphabetic';
   ctx.fillStyle=c?(dark?'#3a2402':'#523502'):(dark?'#645b4c':'#8c816f'); ctx.fillText(pc(m)===0?nm:nm.replace(/-?\d+$/,''),x+w/2,y+dip+h-8,w-2); } }
 for(const [m,k] of G.keys){ if(!k.black) continue; const c=tint(m), dip=c?4:0, bh=Math.round(kh*.62)-dip, x=k.x, w=k.w, br=Math.min(3,w*.15);
  ctx.save(); ctx.shadowColor='rgba(0,0,0,.45)'; ctx.shadowBlur=6; ctx.shadowOffsetY=3.5; ctx.fillStyle='rgba(0,0,0,.35)'; fallKeyPath(ctx,x-1,y+dip,w+2,bh,br); ctx.fill(); ctx.restore();
  const g=ctx.createLinearGradient(0,y+dip,0,y+dip+bh);
  if(c){ if(c===FALL_YOU){ g.addColorStop(0,'#e5b344'); g.addColorStop(.55,'#c48c22'); g.addColorStop(.88,'#a16f15'); g.addColorStop(1,'#78500c'); } else { g.addColorStop(0,c[1]); g.addColorStop(1,c[0]); } }
  else { g.addColorStop(0,'#36302a'); g.addColorStop(.45,'#24201c'); g.addColorStop(.78,'#181513'); g.addColorStop(.92,'#2a2520'); g.addColorStop(1,'#141210'); }
  ctx.fillStyle=g; fallKeyPath(ctx,x,y+dip,w,bh,br); ctx.fill();
  ctx.strokeStyle=c?(c===FALL_YOU?'rgba(255,245,190,.5)':'rgba(0,0,0,.6)'):'#0d0b09'; ctx.lineWidth=1; fallKeyPath(ctx,x,y+dip,w,bh,br); ctx.stroke();
  if(wait.has(m)){ ctx.fillStyle='rgba(255,196,64,'+(.45+.4*pulse).toFixed(3)+')'; fallKeyPath(ctx,x,y+dip,w,bh,Math.min(3,w*.15)); ctx.fill(); }
  if(!c){ ctx.strokeStyle='rgba(255,255,255,.16)'; ctx.lineWidth=1; ctx.beginPath(); ctx.moveTo(x+1,y+dip+bh-br); ctx.lineTo(x+1,y+dip+1); ctx.lineTo(x+w-1,y+dip+1); ctx.stroke(); } }
 const felt=ctx.createLinearGradient(0,y,0,y+3.5); felt.addColorStop(0,'#621919'); felt.addColorStop(.5,'#8d2525'); felt.addColorStop(1,'#461212'); ctx.fillStyle=felt; ctx.fillRect(0,y,W,3.5);
 const feltShadow=ctx.createLinearGradient(0,y+3.5,0,y+7.5); feltShadow.addColorStop(0,'rgba(0,0,0,.45)'); feltShadow.addColorStop(1,'rgba(0,0,0,0)'); ctx.fillStyle=feltShadow; ctx.fillRect(0,y+3.5,W,4);
}
// Timeline under the stage: clock, bar ticks, loop region, A/B markers, seek slider and the current bar.
function anTlUpdate(time){
 const tl=$('an-tl'); if(!tl||tl.hidden||!AN.notes.length) return;
 const end=fallEnd(), pos=Math.max(0,Math.min(end,time!=null?time:fallTime())), seek=$('fall-seek'), pct=x=>(end>0?Math.max(0,Math.min(1,x/end))*100:0).toFixed(3)+'%';
 const mx=String(Math.max(.1,end)); if(seek.max!==mx) seek.max=mx;
 if(document.activeElement!==seek||SCORE.playing) seek.value=pos;
 seek.style.setProperty('--p',pct(pos)); seek.setAttribute('aria-valuetext',t('fall_valtext',anClock(pos),anClock(end)));
 const set=(id,v)=>{ const el=$(id); if(el.textContent!==v) el.textContent=v; };
 set('fall-clock',anClock(pos)); set('fall-total',anClock(end));
 const ms=anMeasures(), m=anMeasureAt(scoreBeatAt(pos)); set('tl-bar',m&&ms.length?t('tl_bar',m.number,ms[ms.length-1].number):'');
 if(FALL.tickSrc!==fallData()||FALL.tickTempo!==SCORE.tempoList||FALL.tickEnd!==end){ FALL.tickSrc=fallData(); FALL.tickTempo=SCORE.tempoList; FALL.tickEnd=end;
  const step=ms.length>240?8:ms.length>120?4:ms.length>60?2:1, major=ms.length>60?Math.max(8,step*4):4;
  $('tl-ticks').innerHTML=ms.map((x,i)=>i%step?'':`<i${i%major===0?' class="is-major"':''} style="left:${pct(scoreSeconds(x.start))}"></i>`).join(''); }
 const L=SCORE.loop, lp=$('tl-loop'), A=PRAC.A, B=PRAC.B, la=L?L.a:A!=null&&B!=null?A:null, lb=L?L.b:A!=null&&B!=null?B:null;
 lp.hidden=la==null; if(la!=null){ lp.style.left=pct(la); lp.style.width=(end>0?(lb-la)/end*100:0).toFixed(3)+'%'; }
 [['tl-a',A],['tl-b',B]].forEach(([id,v])=>{ const el=$(id); el.hidden=v==null; if(v!=null) el.style.left=pct(v); });
}
// Seeking pauses while the slider moves and resumes on release if it was playing.
function fallSeek(){ const pos=+$('fall-seek').value; if(SCORE.playing){ FALL.resume=SCORE.loop?null:{sel:SCORE.sel}; scoreHalt(); } SCORE.resume=null; FALL.position=pos; scoreIdle(); }
function fallSeekEnd(){ const r=FALL.resume; FALL.resume=null; if(r) scorePlay(r.sel,FALL.position); }
function fallHit(e){ const r=e.currentTarget.getBoundingClientRect(), x=e.clientX-r.left, y=e.clientY-r.top; return FALL.hits.findLast(h=>x>=h.x-2&&x<=h.x+h.w+2&&y>=h.y&&y<=h.y+h.h); }
// The integrated keyboard is playable by mouse or touch.
function fallKeyAt(e){ const G=FALL.geo; if(!G||!G.hitY) return null; const r=e.currentTarget.getBoundingClientRect(), x=e.clientX-r.left, y=e.clientY-r.top;
 if(y<G.hitY) return null; const bh=G.hitY+G.kh*.62;
 if(y<=bh) for(const [m,k] of G.keys) if(k.black&&x>=k.x&&x<=k.x+k.w) return m;
 for(const m of G.whites){ const k=G.keys.get(m); if(x>=k.x&&x<k.x+k.w) return m; } return null; }
function fallKeyDown(e){ const m=fallKeyAt(e); if(m==null) return; e.preventDefault(); ensureAudio(); FALL.press=FALL.press||new Map();
 FALL.press.set(e.pointerId,m); try{ e.currentTarget.setPointerCapture(e.pointerId); }catch(_){} handleNoteOn(m,96,'fall:'+e.pointerId); if(!FALL.raf) fallDraw(); }
function fallKeyUp(e){ const P=FALL.press, m=P&&P.get(e.pointerId); if(m==null) return; P.delete(e.pointerId); handleNoteOff(m,'fall:'+e.pointerId); if(!FALL.raf) fallDraw(); }
function fallSelect(e){ if(fallKeyAt(e)!=null) return; const hit=fallHit(e), add=e.shiftKey||e.ctrlKey||e.metaKey; if(!hit){ if(!add) anClearSelection(); return; }
 if(!add) AN.selected.clear(); if(AN.selected.has(hit.i)) AN.selected.delete(hit.i); else AN.selected.add(hit.i); anSelectionChanged(); }
function fallHover(e){ e.currentTarget.style.cursor=fallHit(e)||fallKeyAt(e)!=null?'pointer':''; }
/* wiring */
// Score shortcuts, only in this view and never while typing or choosing in a form field:
// Space play/pause, Home go to start, Esc close the settings or clear the selection, + / − zoom.
function anShortcut(e){
 if(view0()!=='analysis'||e.defaultPrevented||e.metaKey||e.ctrlKey||e.altKey||inField()||$('drawer').classList.contains('on')||$('helpBox').classList.contains('on')) return;
 const k=e.key;
 if(k==='Escape'){ if(!$('pr-sum').hidden){ e.preventDefault(); pracSumClose(); return; }
  for(const [p,b] of AN_POPS) if(!$(p).hidden){ e.preventDefault(); anPop(p,false); $(b).focus(); return; }
  if(!$('an-recon').hidden){ e.preventDefault(); anReconOpen(false); $('an-recon-btn').focus(); return; }
  if(SIDE.sheet){ e.preventDefault(); anSheet(false); return; }
  if(anClearSelection()) e.preventDefault(); return; }
 if(!AN.notes.length||AN.loading||e.repeat) return;
 if(k===' '){ if(e.target.closest&&e.target.closest('button,a[href],summary,[role="button"],input,select,textarea')) return; e.preventDefault(); scoreToggle(); return; }
 if(k==='Home'){ e.preventDefault(); scoreHome(); return; }
 if(k==='+'||k==='='){ e.preventDefault(); scoreZoom(anZoomNow()+0.1); return; }
 if(k==='-'||k==='_'){ e.preventDefault(); scoreZoom(anZoomNow()-0.1); return; }
 if(k==='End'){ e.preventDefault(); scoreSeekTo(fallEnd()); return; }
 if(k==='ArrowLeft'||k==='ArrowRight'){ if(e.target.closest&&e.target.closest('[data-i],.an-ch,input,select')) return; e.preventDefault(); scoreSeekBar(k==='ArrowRight'?1:-1); return; }
 const K=k.length===1?k.toLowerCase():k;
 if(K==='l'){ e.preventDefault(); $('an-loop').click(); return; }
 if(K==='['){ e.preventDefault(); pracSetAB('A'); return; }
 if(K===']'){ e.preventDefault(); pracSetAB('B'); return; }
 if(K==='p'){ e.preventDefault(); pracSet('wait',!PRAC.wait); return; }
 if(K==='m'){ e.preventDefault(); pracSet('metro',!PRAC.metro); return; }
 if(K==='c'){ e.preventDefault(); PRAC.countIn=!PRAC.countIn; $('pr-countin').checked=PRAC.countIn; pracSave(); return; }
 if(k==='1'||k==='2'||k==='3'){ e.preventDefault(); pracSet('hands',['both','rh','lh'][+k-1]); }
}
// Seek to a time (keeps playing if it was playing) and step bar by bar.
function scoreSeekTo(x){ x=Math.max(0,Math.min(fallEnd(),x)); if(SCORE.playing&&!SCORE.loop){ scorePlay(SCORE.sel,x); return; }
 if(SCORE.playing) scoreHalt(); SCORE.resume=null; SCORE.paused=false; FALL.position=x; scoreIdle(); }
function scoreSeekBar(d){ const ms=anMeasures(); if(!ms.length) return; const now=SCORE.playing?fallTime():FALL.position, beat=scoreBeatAt(now);
 let i=ms.findIndex(m=>beat<m.end-1e-6); if(i<0) i=ms.length-1;
 if(d<0&&beat-ms[i].start>.5&&!(SCORE.playing&&scoreSeconds(beat)-scoreSeconds(ms[i].start)>.6)) d=0;   // first press goes back to this bar's start
 i=Math.max(0,Math.min(ms.length-1,i+d)); scoreSeekTo(scoreSeconds(ms[i].start)); }
// Popovers under the toolbar: one open at a time, placed under their button, closed by Esc or a click outside.
const AN_POPS=[['fall-pop','fall-opt'],['an-keys-pop','an-keys-btn']];
function anPop(id,open){ const pair=AN_POPS.find(x=>x[0]===id), p=$(id), b=$(pair[1]); open=!!open&&!b.hidden;
 if(open){ AN_POPS.forEach(([q])=>{ if(q!==id) anPop(q,false); }); anReconOpen(false); }
 p.hidden=!open; b.setAttribute('aria-expanded',open?'true':'false');
 if(open&&id!=='an-keys-pop'){ const host=p.offsetParent||p.parentElement, hr=host.getBoundingClientRect(), br=b.getBoundingClientRect(), w=p.offsetWidth;
  p.style.left=Math.max(8,Math.min(hr.width-w-8,br.left-hr.left+br.width/2-w/2))+'px'; p.style.right='auto'; }
 if(open){ const f=p.querySelector('input,select,button'); if(f) f.focus({preventScroll:true}); } }
// The score keeps its engraving while the viewport changes size, unless the page no longer fits (or could be wider again).
function anStageFit(){
 if(view0()!=='analysis'||SIDE.drag) return; if(FALL.mode==='fall'){ fallDraw(); return; }
 const box=$('an-roll'), sheet=box.querySelector('.an-sheet'); if(!SCORE.engine||!box.clientWidth||!sheet) return;
 if(SCORE.layout==='cont'){ if(Math.abs(box.clientWidth-SCORE.layoutWidth)>40) scoreLayout(); return; }
 const cs=getComputedStyle(box), avail=box.clientWidth-parseFloat(cs.paddingLeft)-parseFloat(cs.paddingRight);
 if(Math.abs(sheet.offsetWidth-Math.max(240,Math.round(Math.min(SC_PAGE_W*SCORE.zoom,avail))))>2) scoreLayout(); }
// The panel's left edge resizes it: drag, or arrow keys on the focused separator (Home / End for the narrowest / widest).
function anSideResizer(){
 const h=$('an-side-resize'), work=$('an-work'), MIN=280, MAX=560;
 const apply=(w,save)=>{ SIDE.w=Math.round(Math.max(MIN,Math.min(MAX,work.clientWidth*.5,w))); work.style.setProperty('--an-side-w',SIDE.w+'px'); h.setAttribute('aria-valuenow',String(SIDE.w)); if(save){ saveAll(); anStageFit(); } };
 h.addEventListener('pointerdown',e=>{ if(e.button!==0) return; e.preventDefault(); h.setPointerCapture(e.pointerId); SIDE.drag=true; h.classList.add('is-drag');
  const right=work.getBoundingClientRect().right, move=ev=>apply(right-ev.clientX,false);
  const up=()=>{ h.removeEventListener('pointermove',move); h.removeEventListener('pointerup',up); h.removeEventListener('pointercancel',up); SIDE.drag=false; h.classList.remove('is-drag'); apply(SIDE.w,true); };
  h.addEventListener('pointermove',move); h.addEventListener('pointerup',up); h.addEventListener('pointercancel',up); });
 h.addEventListener('keydown',e=>{ const d={ArrowLeft:16,ArrowRight:-16}[e.key];
  if(d){ e.preventDefault(); apply(SIDE.w+d,true); } else if(e.key==='Home'||e.key==='End'){ e.preventDefault(); apply(e.key==='Home'?MIN:MAX,true); } });
}
